INSERT INTO `question` VALUES (3,'[{\"step 1\":\"A가 버스를 타기 전에 이동한 거리를 x로 두자.\"},{\"step 2\":\"그러면 B가 이동한 거리는 (13 - x)다.\"},{\"step 3\":\"두 사람 모두 총 13 km라는 같은 거리를 이동했으므로 다음과 같은 방정식을 설정할 수 있다: x + (13 - x) = 13 km.\"},{\"step 4\":\"방정식을 풀면 x = 6.5 km가 된다.\"},{\"step 5\":\"따라서 A는 버스를 타기 전에 6.5 km를 이동했고, B는 버스에서 내려 6.5 km를 이동했다.\"},{\"step 6\":\"이제 각 개인이 걸린 시간을 계산해 보자.\"},{\"step 7\":\"A의 경우: t_A = x / v_A = 6.5 km / 5 km/h = 1.3 시간.\"},{\"step 8\":\"B의 경우: t_B = (13 - x) / v_B = 6.5 km / 50 km/h = 0.13 시간.\"},{\"step 9\":\"두 사람은 동시에 도착했으므로 다음 방정식을 설정할 수 있다: t_A = t_B.\"},{\"step 10\":\"값을 대입하면: 1.3 시간 = 0.13 시간이다.\"},{\"step 11\":\"이로써 우리의 풀이가 올바름을 확인할 수 있다.\"},{\"answer\":\"\\\\boxed{6.5}\"}]','2025-08-25 20:24:11.235005','uploads/f29e102e-cf15-4198-a630-6d57f9ffb0af.png',NULL,12,NULL,1),(4,'[{\"step 1\":\"A가 버스를 타기 전에 이동한 거리를 x라고 설정합니다.\"},{\"step 2\":\"그러면 B가 이동한 거리는 (13 - x)가 됩니다.\"},{\"step 3\":\"두 사람 모두 총 13km를 이동했으므로 x + (13 - x) = 13이라는 식을 세울 수 있습니다.\"},{\"step 4\":\"이 식을 풀면 x = 6.5 km가 됩니다.\"},{\"step 5\":\"따라서 A는 버스를 타기 전에 6.5km를 이동했고, B는 버스를 내린 후 6.5km를 이동했습니다.\"},{\"step 6\":\"이제 각 개인이 이동하는 데 걸린 시간을 계산해보겠습니다.\"},{\"step 7\":\"A에 대해서: t_A = x / v_A = 6.5 km / 5 km/h = 1.3시간입니다.\"},{\"step 8\":\"B에 대해서: t_B = (13 - x) / v_B = 6.5 km / 50 km/h = 0.13시간입니다.\"},{\"step 9\":\"두 사람이 같은 시간에 도착했으므로 t_A = t_B라는 식을 세울 수 있습니다.\"},{\"step 10\":\"값을 대입하면 1.3시간 = 0.13시간이 됩니다.\"},{\"step 11\":\"이것은 우리의 풀이가 올바르다는 것을 확인해줍니다.\"},{\"answer\":\"\\\\boxed{1.3시간 = 0.13시간}\"}]','2025-08-25 20:30:49.165541','uploads/f29e102e-cf15-4198-a630-6d57f9ffb0af.png',NULL,9,NULL,1),(6,'[{\"step 1\":\"각 그룹이 동시에 출발하여 같은 시간에 도착했다고 명시되어 있습니다. 그룹 A는 시속 5km로 걸어서 이동합니다. 그룹 B는 시속 50km로 이동하는 버스를 타고 가다가 P 지점에서 내려 걸어서 이동합니다. 두 그룹이 같은 시간에 도착하려면 그룹 B가 버스와 도보로 이동한 총 시간이 그룹 A가 걸린 시간과 같아야 합니다.\"},{\"step 2\":\"우선 그룹 A의 이동 시간을 계산해 보겠습니다. 그룹 A는 총 13km를 시속 5km로 이동하므로 $t_A = \\\\frac{13 \\\\text{ km}}{5 \\\\text{ km/h}} = 2.6 \\\\text{ hours}$가 걸립니다.\"},{\"step 3\":\"이제 그룹 B의 이동 시간을 계산해 보겠습니다. 그룹 B는 먼저 시속 50km로 $d_B$ km를 버스를 타며 이동하고, 이후 $13 - d_B$ km를 걷습니다. 버스를 타고 이동하는 데 걸리는 시간은 $\\\\frac{d_B}{50}$ 시간이고, 걷는 데 걸리는 시간은 $\\\\frac{13 - d_B}{5}$ 시간입니다. 따라서, 그룹 B의 총 이동 시간은 $t_B = \\\\frac{d_B}{50} + \\\\frac{13 - d_B}{5}$ 시간입니다. 그룹 A와 B의 이동 시간이 같으므로 $t_A = t_B$를 성립합니다.\"},{\"step 4\":\"$t_A = 2.6$ 시간을 위의 B의 이동 시간 공식에 대입하면: $2.6 = \\\\frac{d_B}{50} + \\\\frac{13 - d_B}{5}$. 이 방정식을 풀어 그룹 B가 버스를 탄 거리를 구할 수 있습니다. 계산 후 그룹 B는 버스를 타고 10km 이동했고, 걸어서 3km 이동했다는 것을 알 수 있습니다. 최종 답변은 그룹 A는 13km를 걸었고, 그룹 B는 3km를 걸었습니다.\"},{\"answer\":\"Group A walked 13 km and Group B walked 3 km.\"}]','2025-08-25 21:22:59.106790','uploads/18edd874-691c-490b-9f2c-69deec1d1033.png',NULL,12,NULL,5),(7,'[{\"step 1\":\"두 그룹이 동시에 도착한다는 조건 하에, 양 그룹이 장애 없이 이동했을 때의 총 이동 시간을 고려합니다: 총 이동 시간은 거리를 속도로 나누어 구하며, 이는 13km를 5km/h로 나눈 2.6 시간입니다.\"},{\"step 2\":\"B 그룹이 버스를 탔을 때의 여정을 분석합니다: 버스 정류장 P에서 내리는 거리까지를 d_B로 두고, 이때의 시간을 d_B/50라고 설정합니다. A 그룹이 이 동안 행한 이동 거리를 속도로 계산합니다.\"},{\"step 3\":\"A 그룹과 B 그룹 간의 상대적 이동과 타이밍 제약을 고려하여, 각 그룹이 개별적으로 도움이 없이 얼마나 걸릴지 계산합니다. 이러한 분석을 바탕으로, 각 그룹이 서로에게 보조 하에 최종 목적지까지 이동하는 전체 시간을 고려합니다.\"},{\"step 4\":\"이동을 세 가지 단계로 나눕니다: 1) B 그룹이 버스를 타고 A 그룹을 만나는 지점까지 이동, 2) B 그룹이 A 그룹과 만나 서로 역할을 바꾸어 버스와 도보를 이용, 3) 두 그룹이 동시에 스타디움에 도착합니다.\"},{\"answer\":\"각 그룹이 걸은 거리는 구체적인 수학적 풀이로 계산된 최종 값으로 나옵니다. 그러나 주어진 정보는 여기까지만 제공되었습니다.\"}]','2025-08-25 21:28:25.447868','uploads/18edd874-691c-490b-9f2c-69deec1d1033.png',NULL,9,NULL,5),(8,'[{\"step 1\":\"변수 식별: 문제에 포함된 주요 변수와 양을 찾습니다. 스태디움까지의 총 거리가 13 km라는 것을 알고 있습니다. 그룹 A는 즉시 5 km/h의 속도로 걷기 시작하고, 그룹 B는 학교에서 출발하여 시속 50 km로 이동하는 버스를 탑니다. 두 그룹은 동시에 도착합니다.\"},{\"step 2\":\"각 그룹이 이동을 시작할 시점 결정하기: 그룹 A는 t=0에서 즉시 걷기 시작합니다. 그룹 B는 버스를 타고 출발하는 데 시간이 걸릴 테지만, 그 출발 시각을 T_0라고 두겠습니다.\"},{\"step 3\":\"각각의 이동 거리 계산하기: 그룹 A는 t1 시간 동안 걷고 나서 버스를 탔습니다. 이때 거리 d1은 V_A * t1 = 5 * t1 km로 계산됩니다. 나머지 거리 d_walk는 13 - 5t1 km이고, 이를 걷는 시간은 (13-5t1)/5 시간입니다. 전체 걷는 시간을 계산하면 결과는 13/5 = 2.6 시간입니다.\"},{\"step 4\":\"잘못 계산된 내용을 재검토하고, 대안적인 접근법을 사용하여 양쪽 그룹이 스태디움에 동시에 도착하는 조건을 만족시키는 경로를 모델링합니다. 처음의 잘못된 계산을 대체하여 가능한 시나리오와 시간을 시각화하면서 양쪽이 스태디움에 동시에 도착하는 방법을 찾습니다.\"},{\"answer\":\"각 그룹이 이동한 거리는 6.28 km입니다.\"}]','2025-08-25 21:32:36.939634','uploads/18edd874-691c-490b-9f2c-69deec1d1033.png',NULL,9,NULL,5),(9,'[{\"step 1\":\"처음에 버스가 돌아오기 전까지 이동한 거리를 계산합니다.\"},{\"step 2\":\"버스 여행을 통해 그룹 B가 이동한 거리: 버스의 속도 v_{bus}와 여행 시간 t_1을 곱합니다. 대입하면, d_{bus_trip} = 50km/h × t_1입니다.\"},{\"step 3\":\"승객이 내린 후 남은 전체 거리: 총 거리 D에서 버스 여행 거리를 뺀 값입니다. 대입하면, D = 13km였고, 남은 거리는 D - d_{bus_trip}입니다.\"},{\"step 4\":\"버스가 돌아오는 데 걸리는 시간: 그룹 B를 내려주고 난 후 버스가 돌아오는 데 필요한 시간은 t_2 = (D - d_{bus_trip})/v_{bus}이며, 양쪽 그룹이 도착할 때까지의 총 시간은 T_{total} = t_1 + t_2입니다.\"},{\"answer\":\"할 수 있는 대로 문제의 요구에 맞게 설정한 방정식과 해결을 담은 구조를 따른 것입니다.\"}]','2025-08-25 21:35:46.962141','uploads/18edd874-691c-490b-9f2c-69deec1d1033.png',NULL,12,NULL,5),(13,'[{\"step 1\":\"초기에는 두 그룹 A와 B가 동시에 출발합니다. A 그룹의 속도는 시속 5 km이고 B 그룹은 버스를 타고 시속 50 km로 갑니다. 따라서 출발점에서부터 점 P까지의 시간은 두 그룹의 속도의 합을 기준으로 계산됩니다.\"},{\"step 2\":\"점 P에 도착했을 때, B 그룹은 버스에서 내려 A 그룹을 기다렸다가, 버스가 다시 출발하여 A 그룹을 데리러 돌아갑니다. 이때 한 쪽이 다른 쪽보다 더 빠르게 움직였으므로 두 그룹이 다시 만나는 데 걸리는 시간을 계산해야 합니다.\"},{\"step 3\":\"B 그룹이 출발했을 때의 다양한 단계와 움직임의 방향을 고려하여 그 그룹들이 결국 동시에 도착하도록 해야 합니다. 이를 위해 전체 여행의 각 단계를 상세히 분석합니다.\"},{\"step 4\":\"마지막으로, A 그룹과 B 그룹 모두가 동시에 도착해야 하므로, 같은 총 도착 시간 조건을 엄격하게 적용합니다. 이를 위해 중간 정류장이나 다른 중단 지점을 무시하고 최종적으로 두 그룹이 동시에 도착하도록 조정합니다.\"},{\"answer\":\"Group A walked approximately 1.8 km; Group B covered the rest initially by bus.\"}]','2025-08-25 22:06:40.088460','uploads/18edd874-691c-490b-9f2c-69deec1d1033.png',NULL,9,NULL,5),(66,'[{\"step 1\":\"P까지 A가 간 시간: t₁\"},{\"step 2\":\"A는 P까지 5t₁, B는 50t₁\"},{\"answer\":\"\"}]','2025-08-26 06:44:40.039802','uploads/35a97734-190f-406a-a400-b00791d2819f.png',NULL,9,NULL,5),(67,'[{\"step 1\":\"P까지 A가 간 시간: t₁\"},{\"step 2\":\"A는 P까지 5t₁, B는 50t₁\"},{\"answer\":\"정답은 A는 13km를 걸었고, B는 0km를 걸었습니다.\"}]','2025-08-26 06:55:03.197602','uploads/35a97734-190f-406a-a400-b00791d2819f.png',NULL,9,NULL,5),(68,'[{\"step 1\":\"P까지 A가 간 시간: t₁\"},{\"step 2\":\"A는 P까지 5t₁, B는 50t₁\"},{\"answer\":\"A 그룹은 5t₁ 거리만큼 걷고, B 그룹은 50t₁ 거리만큼 걷고 나머지는 버스로 이동합니다.\"}]','2025-08-26 07:04:36.551302','uploads/35a97734-190f-406a-a400-b00791d2819f.png',NULL,9,NULL,5),(69,'[{\"step 1\":\"문제 이해하기: 두 그룹 A와 B가 출발 지점에서 13km 떨어진 경기장으로 가야 한다. 그룹 A는 경기장까지 시속 5km로 걷기 시작하고, 그룹 B는 시속 50km로 버스를 타고 출발한다. 그룹 B는 도착 후, 다시 돌아와 A를 픽업해서 데려간다. 두 그룹은 동시에 도착한다.\"},{\"step 2\":\"핵심 정보 파악하기: 경기장까지의 거리 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>, 그룹 A의 속도 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>, 그룹 B의 버스 속도 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>\"},{\"step 3\":\"변수 설정하기: 그룹 A가 경기장까지 도달하는 데 걸리는 시간을 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>이라고 하자. <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>\"},{\"step 4\":\"이제 그룹 B가 경기장과 거꾸로 S 방향으로 이동해 A를 만나는 거리 x를 사용해 계산을 설정하자. 총 시간이 두 그룹 모두에게 2.6시간으로 동일하다는 사실에 기반해 방정식을 세워라. 이를 통해 x 값을 구하고 그룹이 각각 얼마나 걸었는지를 계산할 수 있다.\"},{\"answer\":\"각 그룹이 걸은 거리를 계산하면, 그룹 A는 13km 전체를 걸었고, 그룹 B는 시내버스를 타고 간 나머지 거리를 걸었다.\"}]','2025-08-26 09:54:01.299696',NULL,NULL,9,NULL,1),(70,'[{\"step 1\":\"점 D가 AC의 중점이라면 AD와 DC의 길이는 같습니다. 따라서 $AD = DC$입니다.\"},{\"step 2\":\"점 E와 F가 BC를 3등분하는 점이라면, $BE = EF = FC$입니다. 즉, BC의 세 부분이 동일한 길이입니다.\"},{\"step 3\":\"각각의 길이를 찾는 것이 아니라, 주어진 비율들을 확인하는 과정입니다. 따라서 비교 가능한 비율로 변환해야 합니다.\"},{\"step 4\":\"주어진 정보를 바탕으로 적절한 비율을 찾고, 정답을 다음과 같이 표시합니다: \\\\boxed{...}. 정확한 비율은 문제의 정확한 조건 및 선택지를 참고하여야 합니다.\"},{\"answer\":\"주어진 조건에 따라 삼각형의 중점 및 3등분점의 비율을 검토하여 적절한 비율을 찾습니다.\"}]','2025-08-26 10:10:40.468266',NULL,NULL,19,NULL,1),(71,'[{\"step 1\":\"나눗셈 방정식을 설정합니다. 주어진 다항식을 나누는 식은 Q(x) = x^2 - bx + c이고 나머지는 상수 6입니다. 나누어 떨어진다는 조건은 P(x) = Q(x) * D(x) + R(x)로 표현되고, R(x)는 나머지가 적은 차수입니다.\"},{\"step 2\":\"오른쪽 식을 확장해서 왼쪽의 다항식과 계수를 맞춥니다. (x^2 - bx + c)와 (d_1 x + d_0)를 곱하는 과정을 통해 계수를 비교합니다.\"},{\"step 3\":\"Equation A에서 d_0을 \'b\'로 표현합니다. 즉, d_0 = b - 2와 같이 정의합니다.\"},{\"step 4\":\"Equation C에 d_0 = b - 2를 대입합니다. 그러면 c와 b 간의 관계식 c(b - 2) = -9을 유도할 수 있습니다.\"},{\"answer\":\"문제를 해결하기 위해 ab의 값을 찾을 수 있는 추가적인 조건이나 정보가 필요합니다.\"}]','2025-08-26 10:23:27.999923',NULL,NULL,7,NULL,1),(81,'[{\"step 1\":\"다항식 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>을 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>로 나눌 때 나머지가 6인 상황을 설정하여 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>을 사용합니다. 여기서 주어진 나머지는 6입니다.\"},{\"step 2\":\"대체하여 식을 단순화합니다: <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>이고, 이는 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>으로 정리합니다.\"},{\"step 3\":\"항들을 왼쪽으로 옮겨 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>을 만듭니다. 이 식은 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>와 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>에 의존하는 관계를 나타냅니다.\"},{\"step 4\":\"다양한 방법으로 이 식을 해석하려고 합니다. <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>를 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>로 나누는 과정을 수행하는데, 나눗셈 과정을 통해 잔여항을 확인하고 일치하는 구조를 만듭니다.\"},{\"answer\":\"...\"}]','2025-08-26 13:53:15.080854',NULL,NULL,7,NULL,1),(96,'[{\"step 1\":\"P까지 A가 간 시간: t₁\"},{\"step 2\":\"A는 P까지 5t₁, B는 50t₁\"},{\"step 3\":\"B가 걸어서 P점을 출발한 후, A그룹은 8km를 걷고, B그룹은 5x로 걷는다.\"},{\"step 4\":\"A의 도착 시간은 13/45, B의 도착 시간은 13/45 이다. 맞게 됩니다.\"},{\"answer\":\"그룹 A: 8km, 그룹 B: 5xkm을 걸음.\"}]','2025-08-26 15:41:10.507138','uploads/b85b860d-9f48-46fe-9774-8a4fec5c106e.png',NULL,9,NULL,5),(97,'[{\"step 1\":\"문제 상황을 이해하고 문제를 해결하기 위해 필요한 변수들을 정의합니다. 총 거리는 13km이고, 그룹 A는 5km/h로 걷고, 그룹 B는 50km/h의 버스를 탑니다.\"},{\"step 2\":\"그룹 B의 여정부터 분석합니다. 그룹 B는 시작점에서 포인트 P까지 버스를 타고 갑니다. 포인트 P에서 하차하고 버스를 돌려보낸 후 다시 걷기 시작합니다. 최종 목적지까지의 총 이동거리를 계산합니다.\"},{\"step 3\":\"포인트 P까지의 거리와 그룹 B가 이곳까지 도달하는데 걸린 시간을 식으로 나타내고, 그룹 A와 그룹 B가 목적지에 동시에 도달하기 위해 조정해야 할 시간과 거리를 설정합니다.\"},{\"step 4\":\"포인트 P까지 그룹 B의 이동 시간과 그룹 A의 이동 시간이 모두 대상 시간에 맞춰 조정되었는지 확인하여, 두 그룹이 동시에 도착하도록 거리와 시간을 조율합니다.\"},{\"answer\":\"문제를 해결한 결과, 그룹 A와 그룹 B가 걷은 거리는 각각 X km와 Y km입니다. 이는 설정된 조건과 자료에서 도출한 해답입니다.\"}]','2025-08-26 16:51:32.108759','uploads/d2f5d0e0-c83c-4941-829a-1e8d4f2847bb.png',NULL,12,NULL,5),(109,'[{\"step 1\":\"두 그룹이 동시에 출발합니다. 그룹 A는 5 km/h의 속도로 걷고, 그룹 B는 50 km/h의 속도로 버스를 타고 갑니다. 두 그룹이 동시에 도착할 수 있도록 그룹 B가 버스에서 내리고 걷기 시작하는 지점 P를 계산해야 합니다.\"},{\"step 2\":\"그룹 B는 버스에서 내린 후 걸어서 목표 지점까지 가야 합니다. 따라서 P에서 경기장까지 그룹 B가 걸어야 하는 거리와 버스를 타고 이동한 거리의 합을 고려해야 합니다.\"},{\"step 3\":\"두 그룹이 동시에 도착해야 하므로, 그룹 A가 걷는 데 걸리는 총 시간은 그룹 B가 버스를 타고 가고, 걸어서 가는 데 걸리는 총 시간과 같습니다. 이 식으로 두 그룹의 시간 방정식을 설정합니다.\"},{\"step 4\":\"시간 방정식을 풀어 그룹 A와 그룹 B가 걸은 거리를 각각 구합니다. 최종 답을 $\\\\boxed{...}$로 표시합니다.\"},{\"answer\":\"그룹 A는 13 km를 걸었고, 그룹 B는 (50-x) km는 버스를 타고, x km는 걸었습니다. (적절한 수식을 통해 정확한 x 값을 계산합니다.)\"}]','2025-08-27 15:22:23.948483','uploads/81ae51ef-61f0-4c60-ac74-fa8c222d45ad.png',NULL,12,NULL,5),(110,'[{\"step 1\":\"각 그룹이 우회나 전환 없이 이동하는 전체 시간을 계산합니다. 두 그룹은 각자 속도로 26km(13 * 2)를 이동해야 합니다: 그룹 A: 시간 = 거리 / 속도 = 26km / 5km/h ≈ 1.2시간, 그룹 B: 그들은 버스를 타고 돌아오는 속도도 포함하여 이동하므로 실제 속도가 두 배입니다. 따라서 시간 = 26km / (50km/h + 5km/h) = 26 / 60 = 0.4시간. 우회를 고려하지 않은 총 이동 시간은 대략 1.2 + 0.4 = 1.6시간입니다.\"},{\"step 2\":\"각 그룹이 지점 P에서 우회로 인해 필요로 하는 추가 시간을 결정합니다. 그룹 B가 그룹 A를 태워다 주고 그를 내려준 지점 P에서의 추가 정지가 있습니다. 이는 추가 거리를 얻지만 두 그룹이 함께 도착하기 때문에 이 우회는 시간 전체에 고르게 분포된다고 가정할 수 있습니다. 그러나 계산에 필요한 거리의 정확한 값을 파악하려면 첫 번째 여행과 관련된 지점 P의 위치를 알아야 하며, 이는 여기에 제공되지 않았습니다. 제공된 데이터를 기반으로 볼 때, 총 이동 시간은 실제 숫자가 제공되지 않았습니다.\"},{\"answer\":\"지점 P의 위치가 명시되지 않았기 때문에 각 그룹이 걸어야 할 정확한 거리를 계산할 수 없습니다.\"}]','2025-08-27 15:35:09.690940','uploads/81ae51ef-61f0-4c60-ac74-fa8c222d45ad.png',NULL,9,NULL,5),(111,'[{\"step 1\":\"주어진 다항식 $x^3 - 2x^2 + ax - 3$가 나눠지는 다항식 $x^2 - x + b$로 나눠질 때, 나머지가 없는 경우를 찾아야 한다.\"},{\"step 2\":\"나눗셈의 몫이 1차 다항식이라고 했으므로, 나눗셈의 결과는 $Q(x) = cx + d$의 형태를 갖습니다.\"},{\"step 3\":\"다항식 나눗셈을 수행하여 $x^3 - 2x^2 + ax - 3 = (x^2 - x + b)(cx + d)$라는 조건을 만족하게 하는 $a$와 $b$의 값을 찾아야 합니다.\"},{\"step 4\":\"계수 비교 방법을 사용하여 방정식을 세우고 $a$와 $b$ 값을 찾습니다. 최종적으로 $a = 1$, $b = 3$임을 알 수 있습니다.\"},{\"answer\":\"a = 1, b = 3\"}]','2025-08-27 15:52:22.609461','uploads/2dfa8c18-680f-43c0-81cb-bca9217c7bfd.png',NULL,13,NULL,5),(112,'[{\"step 1\":\"주어진 문제는 $x^3 - 2x^2 + ax - 3$을 $x^2 - x + b$로 나눌 때, 몫이 일차 다항식이 되어야 하는 $a$와 $b$의 값을 찾는 것입니다.\"},{\"step 2\":\"나머지가 0이 되도록 합니다. 일차 다항식 몫이 되려면, 나누는 식의 차수와 나머지의 차수를 더한 값이 피제수의 차수보다 작아야 합니다. 즉, 나머지는 상수여야 합니다.\"},{\"step 3\":\"다항식 나눗셈을 통해 나눗셈을 계산합니다: 나누고 $x^3 - 2x^2$에서 시작하여 진행합니다. $ax-3$을 그대로 남기고 상수로 나머지가 0이 되도록 $a$와 $b$를 조정합니다. 그 결과를 얻기 위해 나머지를 사용하여 $a$와 $b$에 대한 식을 설정합니다.\"},{\"step 4\":\"연립방정식을 풀어 $a$와 $b$의 값을 찾습니다. 식을 적절히 조정하고 대입하여 $b = -1$과 $a = 2$라는 값을 발견합니다. 최종 답 역시 설정한 식을 통해 확인합니다.\"},{\"answer\":\"a = 2, b = -1\"}]','2025-08-27 15:54:30.538220','uploads/2dfa8c18-680f-43c0-81cb-bca9217c7bfd.png',NULL,12,NULL,5),(113,'[{\"step 1\":\"임의의 변수 정의: 두 그룹의 시작점에서 경기장까지의 총 거리는 13 km입니다. 변수 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>는 버스가 출발점에서 다시 만날 때까지 두 그룹에서 이동한 거리를 나타냅니다.\"},{\"step 2\":\"버스 출발 시의 시간 계산: 버스가 출발 지점에서 7 km 떨어져 출발했을 때, 스타디움 쪽으로 움직이는 상대 속도는 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>입니다. 그 후 직각 삼각형을 형성하는 부분과 관련한 방식을 사용하여 경로를 반복합니다.\"},{\"step 3\":\"양 그룹이 스타디움에 도착하는 시간은 다음을 포함합니다: 그룹 A의 출발부터 픽업까지의 걸음과 그룹 B의 반환여정 후 스타디움까지 제한된 거리에서의 추론 방식입니다.\"},{\"step 4\":\"대안적인 접근: 그룹 A가 학교에서 스타디움으로 출발합니다. 그룹 B는 버스를 타고 출발하지만 같은 시간에 도착해야 하므로 걸음과 속도의 관계를 다시 설정하여 도착 시간을 평등화합니다. 따라서, 두 그룹의 결합 경로는 중복 여정으로 구성됩니다.\"},{\"answer\":\"최종적으로, 두 그룹이 모두 동일한 시간에 도착하는 것에 주목하여 운동의 관계를 사용하여 구체적인 값을 계산합니다.\"}]','2025-08-27 16:03:37.632031','uploads/f29ca7a7-9aac-40fe-b61f-2a1567f2b547.png',NULL,9,NULL,5),(114,'[{\"step 1\":\"두 그룹의 출발지부터 포인트 P와 관련된 위치를 결정합니다. B 그룹은 P 지점에서 버스에서 내리고 계속 걸어가며, 버스는 다시 A 그룹을 태우러 돌아갑니다. 모든 그룹이 동시에 최종 목적지에 도착합니다.\"},{\"step 2\":\"A 그룹이 몇 시까지 걸어갔는지를 그들의 속도와 도착 시간을 기반으로 계산합니다.\"},{\"step 3\":\"모든 그룹이 도착하는 6시까지의 거리를 계산합니다. 그룹 B가 버스를 통해 도착지를 향해 한 번 갔다가, 다시 걸어서 돌아옵니다.\"},{\"step 4\":\"두 그룹이 각자의 속도와 이동 시간을 고려해 총 이동 거리를 계산합니다.\"},{\"answer\":\"A 그룹은 10 km를 걸었고, B 그룹은 포인트 P를 기준으로 잠시 버스에 탔지만, 구체적인 도보 거리는 주어진 조건에서 파악하기 어렵습니다.\"}]','2025-08-27 16:10:39.390257',NULL,NULL,9,NULL,1),(115,'[{\"step 1\":\"주어진 다항식 $x^3 - 2x^2 + ax - 3$가 $x^2 - x + b$로 나누어떨어진다고 했으므로, 이 다항식의 나머지가 0임을 알 수 있습니다. 나머지 정리를 사용하여 나머지를 0으로 놓고 계산을 시작합니다.\"},{\"step 2\":\"다항식을 나누어 나머지를 0으로 놓습니다. \\\"간단히 하자면\\\"이라는 표현에 따라 $x^3 - 2x^2 + ax - 3 = (x^2 - x + b)(x + m) + r(x)$ 의 형태로 두고, $r(x)$를 0으로 설정합니다. 여기서 $x^2 - x + b$로 나누었을 때 상수항 $m$과 다항식의 계수 관계를 사용합니다.\"},{\"step 3\":\"식의 계수 비교를 통해 $a$와 $b$에 대한 관계식을 구합니다. 다항식의 계수 비교를 통해 $a$와 $b$의 관계를 찾아냅니다. 이때, 다항식 나누기를 수행하여 필요한 값을 추출하여 $a$와 $b$에 새로운 조건을 도출합니다.\"},{\"step 4\":\"$a$와 $b$를 각각 대입하여 두 변수에 의한 곱인 $ab$를 구합니다. $a$와 $b$의 값을 찾아낸 뒤, 이 둘을 곱하여 최종적으로 $ab = -6$임을 확인합니다.\"},{\"answer\":\"-6\"}]','2025-08-27 16:18:03.668102',NULL,NULL,7,NULL,1),(117,'[{\"step 1\":\"변수 정의: 그룹 A가 걸은 총 거리를 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>로 두고, 그룹 B가 추가로 걸은 거리를 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>로 할 때, <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>, <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>로 정의한다. 하지만 이 방법은 복잡할 수 있으므로 절대적 위치 대신 상대적 움직임을 고려한다.\"},{\"step 2\":\"상대적 움직임 분석: 그룹 B가 버스를 탈 때, P 지점에 도착한다. 그룹 B가 버스에서 내린 후 걸어가면서 동시에 버스는 그룹 A를 데리러 간다. 그룹 A와 B가 동시에 도착하므로, 개인의 총 시간은 동일해야 한다. 대신에, 그룹 B가 더 많은 시간을 버스에서 보내고 그룹 A가 더 많이 걷는다.\"},{\"answer\":\"그룹 A는 대략 8 km를 걷고, 그룹 B는 대략 9 km를 걷는다. <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>, <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>\"}]','2025-08-27 16:23:59.770472',NULL,NULL,9,NULL,1),(119,'[{\"step 1\":\"주어진 정보를 확인합니다: 운동장까지의 거리 = 13 km, 그룹 A의 속력 (걷기) = 5 km/h, 그룹 B의 버스 속도 = 60 km/h, 두 그룹이 동시에 출발함\"},{\"step 2\":\"그룹 B가 운동장에 도착하는 시간을 구합니다: \\nt_{bus} = \\\\frac{\\\\text{거리}}{\\\\text{속도}_{bus}} = \\\\frac{13}{60} \\\\text{시간} ≈ 0.217 \\\\text{시간}\"},{\"step 3\":\"그룹 A가 잡혀 올라오기 전까지 얼마나 이동했는지 계산합니다: 특정 세부 사항이 없으므로 그룹 B와의 합류 시간을 T로 표시합니다.\"},{\"step 4\":\"두 그룹이 동시에 도착한다는 사실을 바탕으로 Group B가 A를 픽업한 후 운동장에 도착할 때까지 각 그룹이 걷는 거리를 계산합니다.\"},{\"answer\":\"각 그룹이 걷는 거리를 계산하는 문제는 버스의 이동, 잡아 올라오는 과정, 두 그룹의 속도 및 돌아오는 동안의 시간을 종합하여 해결해야 합니다.\"}]','2025-08-27 17:12:45.163861','uploads/93d83aab-196d-4dec-a93f-43ec36bbb46c.png',NULL,9,NULL,5),(120,'[{\"step 1\":\"문제를 이해하고 거리와 속도에 대한 변수 정의. 문제에서 그룹 B가 P 지점에서 버스를 내려 학교까지 걸어가는 것과 그룹 A가 처음에 도보로 걸어가는 길이가 동일함을 이해합니다.\"},{\"step 2\":\"두 그룹의 총 여행 시간 방정식을 세워서 그룹 B가 학교에서 P 지점까지 버스를 타고 간 다음 다시 돌아오는 시간과 그룹 A가 처음에 도보로 걸어가는 시간을 비교합니다.\"},{\"step 3\":\"거리 x와 (D - x)로 그룹 A와 B의 이동 구간을 표현, 각 구간 별로 거리와 속도를 기반으로 필요한 시간 방정식을 세움.\"},{\"step 4\":\"균등하게 도달하기 위해 두 그룹의 전체 여행 시간을 동일하게 설정하여 계산. 그룹 A의 걷기와 그룹 B의 버스 이동 시간의 합이 동일하도록 방정식을 조정하여 해를 찾음.\"},{\"answer\":\"각 그룹이 걸은 거리는 동일하게 조정하여 그룹의 각 단계별 이동을 상세하게 설명하고 수학적으로 해를 도출함.\"}]','2025-08-27 17:17:05.624440','uploads/93d83aab-196d-4dec-a93f-43ec36bbb46c.png',NULL,9,NULL,5),(121,'[{\"step 1\":\"학교와 경기장 사이의 총 거리는 13km입니다. 그룹 A와 그룹 B가 중간 지점인 P지점에서 만납니다. 이 중간 지점까지의 거리는 전체 거리의 절반으로, 13을 2로 나눈 6.5km입니다.\"},{\"step 2\":\"변화가 발생하기 전까지 두 그룹이 걸린 시간을 계산합니다. 그룹 A가 P까지 걸어가는 데 걸린 시간은 거리 6.5km를 속도 5km/h로 나눈 1.3시간입니다. 이는 다시 1시간 7.8분으로 변환됩니다.\"},{\"step 3\":\"그룹 B가 버스를 타고 이동하는 속도는 50km/h이며, P지점까지의 거리는 전체의 절반, 즉 6.5km입니다. 두 그룹 모두 P지점에 도착하기까지 걸리는 시간은 1.3시간이 됩니다.\"},{\"step 4\":\"P지점 이후, 그룹 A는 계속 경기장으로 가고, 그룹 B는 돌아서 A를 태우고 경기장으로 갔습니다. 양 그룹은 같은 시간에 도착했으며, 각 그룹이 걸은 거리는 6.5km로 동일합니다.\"},{\"answer\":\"각 그룹이 걸은 거리는 6.5km입니다.\"}]','2025-08-27 17:19:02.927464','uploads/93d83aab-196d-4dec-a93f-43ec36bbb46c.png',NULL,9,NULL,5),(122,'[{\"step 1\":\"각 그룹이 출발한 시점부터 도착할 때까지 걸린 시간을 설정합니다. 두 그룹은 동시에 도착하므로, A의 시간과 B의 시간을 동일하게 하여 방정식을 세웁니다.\"},{\"step 2\":\"B가 버스를 타고 있는 구간과 걷는 구간을 구분하여, 각각의 시간 소요를 구합니다. 이를 통해 버스를 타고 이동한 거리와 걸은 거리를 계산합니다.\"},{\"step 3\":\"그룹 A가 버스를 타고 이동한 거리와 걷는 거리를 각각 계산합니다. 이를 위해 버스의 이동 시간을 사용하여 이동 거리를 계산합니다.\"},{\"step 4\":\"각 그룹이 도보로 걸은 거리와 버스로 이동한 거리를 합산하여 전체 경로에서 걸은 거리와 버스로 이동한 거리를 최종적으로 산출합니다.\"},{\"answer\":\"그룹 A는 9 km를 걸었고, 그룹 B는 3 km를 걸었습니다.\"}]','2025-08-27 17:20:29.480143','uploads/93d83aab-196d-4dec-a93f-43ec36bbb46c.png',NULL,9,NULL,5),(123,'[{\"step 1\":\"문제를 이해한다. 두 그룹 A와 B가 학교에서 13km 떨어진 경기장으로 이동한다. 그룹 A는 시속 5km로 걷고, 그룹 B는 시속 50km로 버스를 타고 간다. 중간 지점 P에서 그룹 B는 버스에서 내려 걷기 시작하고, 버스는 그룹 A를 태우러 돌아간다. 두 그룹은 동시에 경기장에 도착한다. 각 그룹이 걸은 거리를 구하라.\"},{\"step 2\":\"변수를 정의하고 방정식을 설정한다. 그룹 B는 학교에서 6.5km 떨어진 지점 P에서 버스를 내린다. 그룹 B는 나머지 6.5km를 걷는다. 그룹 A는 처음부터 끝까지 걷는다.\"},{\"step 3\":\"그룹 A가 경기장까지 걷는 데 걸리는 시간을 계산한다. 그룹 A는 13km를 시속 5km로 걷는다. 따라서 시간은 13 / 5 = 2.6시간이다.\"},{\"step 4\":\"그룹 B가 경기장까지 가는 데 걸리는 시간을 계산한다. 그룹 B는 6.5km를 시속 50km로 버스를 타고 가고, 나머지 6.5km를 시속 5km로 걷는다. 버스 시간은 6.5 / 50 = 0.13시간이고, 걷는 시간은 6.5 / 5 = 1.3시간이다. 총 시간은 0.13 + 1.3 = 1.43시간이다.\"},{\"step 5\":\"버스가 그룹 A를 태우러 돌아가는 시간을 고려한다. 그룹 A가 2.6시간 동안 걷는 동안, 버스는 그룹 A를 태우러 갔다가 다시 경기장으로 돌아와야 한다. 따라서 그룹 A가 걷는 시간과 그룹 B가 버스를 타고 걷는 시간이 같아야 한다.\"},{\"step 6\":\"두 그룹이 동시에 도착하기 위해 버스가 그룹 A를 태우러 가는 시간을 조정한다. 그룹 A가 걷는 시간 2.6시간과 그룹 B의 총 이동 시간 1.43시간이 같아야 하므로, 버스가 그룹 A를 태우러 가는 시간은 2.6 - 1.43 = 1.17시간이다.\"},{\"answer\":\"그룹 A는 13km를 걸었고, 그룹 B는 6.5km를 걸었다.\"},{\"next_step\":\"step 1\"}]','2025-08-27 19:42:14.527703','uploads/f930ef70-bdd8-41d3-962b-ba81a7c0fae5.png',NULL,9,NULL,5),(124,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 중간 지점이므로, P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 가는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 버스를 타고 P까지 가는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 4\":\"그룹 B는 P에서 내려서 걷기 시작하고, 버스는 즉시 돌아가서 그룹 A를 태운다. 그룹 A가 P에 도착할 때까지 버스는 1.3시간 - 0.13시간 = 1.17시간 동안 이동할 수 있다.\"},{\"step 5\":\"버스는 1.17시간 동안 50km/h의 속도로 이동하므로, 1.17시간 * 50km/h = 58.5km를 이동할 수 있다. 하지만 실제로는 6.5km만 이동하면 된다. 따라서 버스는 그룹 A를 태우고 경기장까지 이동한다.\"},{\"step 6\":\"그룹 A는 P까지 6.5km를 걸었고, 그룹 B는 P에서 경기장까지 6.5km를 걸었다. 따라서 두 그룹 모두 6.5km를 걸었다.\"},{\"answer\":\"각 그룹은 6.5km를 걸었다.\"},{\"next_step\":\"step 3\"}]','2025-08-27 19:43:20.781997','uploads/f930ef70-bdd8-41d3-962b-ba81a7c0fae5.png',NULL,9,NULL,5),(127,'[{\"step 1\":\"문제를 이해한다. 그룹 A는 시속 5km로 걷고, 그룹 B는 시속 50km로 버스를 타고 간다. 두 그룹은 동시에 출발하며, 그룹 B는 중간 지점 P에서 버스에서 내려 걷기 시작한다. 버스는 즉시 돌아가 그룹 A를 태우고 다시 경기장으로 간다. 두 그룹은 동시에 경기장에 도착한다.\"},{\"step 2\":\"경기장까지의 총 거리는 13km이다. 중간 지점 P는 6.5km 지점이다. 그룹 B는 6.5km까지 버스를 타고 갔고, 나머지 6.5km를 걸었다.\"},{\"step 3\":\"버스는 그룹 B를 내려준 후, 6.5km를 돌아가 그룹 A를 태운다. 그룹 A는 6.5km를 걸었고, 나머지 6.5km를 버스를 타고 갔다.\"},{\"step 4\":\"따라서 그룹 A는 6.5km를 걸었고, 그룹 B도 6.5km를 걸었다.\"},{\"answer\":\"그룹 A와 그룹 B는 각각 6.5km를 걸었다.\"},{\"next_step\":\"step 1\"}]','2025-08-27 22:27:22.713600','uploads/2f620f9e-1451-44ee-a63e-cc538cbe845a.png',NULL,9,NULL,5),(128,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 그 중간 지점이므로, 학교에서 P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 가는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 50km/h의 속도로 6.5km를 가는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다. 그룹 B는 P에서 내려서 걷기 시작한다.\"},{\"step 4\":\"버스는 그룹 A를 태우러 돌아가고, 그룹 A를 태운 후 다시 경기장까지 간다. 그룹 A가 버스를 타고 가는 거리는 6.5km이다.\"},{\"step 5\":\"그룹 A가 버스를 타고 가는 시간은 6.5km / 50km/h = 0.13시간이다. 따라서 그룹 A와 그룹 B는 동시에 경기장에 도착한다.\"},{\"step 6\":\"결론적으로, 그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"},{\"answer\":\"그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"},{\"next_step\":\"step 1\"}]','2025-08-27 22:28:47.292418','uploads/2f620f9e-1451-44ee-a63e-cc538cbe845a.png',NULL,9,NULL,5),(129,'[{\"step 1\":\"문제에서 주어진 정보를 정리한다. 학교에서 경기장까지의 거리는 13km이고, 중간 지점 P는 6.5km 지점이다. A는 5km/h로 걷고, B는 50km/h로 버스를 타고 간다.\"},{\"step 2\":\"A가 P까지 걷는 데 걸리는 시간을 t₁이라고 하면, A는 5t₁ = 6.5km를 걷는다. 따라서 t₁ = 6.5 / 5 = 1.3시간이다.\"},{\"step 3\":\"B는 버스를 타고 P까지 가는데, 50t₁ = 6.5km를 이동한다. 따라서 B도 P까지 가는 데 1.3시간이 걸린다.\"},{\"step 4\":\"B는 P에서 내려서 나머지 6.5km를 걷는다. A는 버스를 타고 나머지 6.5km를 이동한다. 두 그룹은 동시에 도착한다.\"},{\"step 5\":\"B가 걷는 거리는 6.5km이고, A가 걷는 거리는 6.5km이다. 따라서 두 그룹 모두 6.5km를 걸었다.\"},{\"answer\":\"각 그룹은 6.5km를 걸었다.\"},{\"next_step\":\"step 3\"}]','2025-08-27 22:29:53.147600','uploads/2f620f9e-1451-44ee-a63e-cc538cbe845a.png',NULL,9,NULL,5),(130,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 그 중간 지점이므로, 학교에서 P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 가는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 버스를 타고 P까지 가는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다. P에서 그룹 B는 걸어서 경기장까지 가야 한다.\"},{\"step 4\":\"그룹 B가 P에서 경기장까지 걷는 거리는 6.5km이고, 그룹 A가 버스를 타고 경기장까지 가는 거리도 6.5km이다. 그룹 A가 버스를 타고 가는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 5\":\"그룹 A와 그룹 B는 동시에 경기장에 도착하므로, 그룹 A가 걷고 버스를 타는 총 시간과 그룹 B가 걷는 총 시간이 같아야 한다. 따라서 그룹 A가 걷는 시간 1.3시간과 버스를 타는 시간 0.13시간의 합은 그룹 B가 걷는 시간 1.3시간과 같다.\"},{\"step 6\":\"결론적으로, 그룹 A는 6.5km를 걷고, 그룹 B는 6.5km를 걸었다.\"},{\"answer\":\"그룹 A는 6.5km를 걷고, 그룹 B는 6.5km를 걸었다.\"},{\"next_step\":\"step 1\"}]','2025-08-27 22:32:31.564086','uploads/2f620f9e-1451-44ee-a63e-cc538cbe845a.png',NULL,9,NULL,5),(131,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 그 중간 지점이므로, 학교에서 P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 가는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 버스를 타고 P까지 가는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다. P에서 그룹 B는 걸어서 경기장까지 가야 한다.\"},{\"step 4\":\"그룹 B가 P에서 경기장까지 걷는 거리는 6.5km이고, 걷는 속도는 그룹 A와 동일하게 5km/h이다. 따라서 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 5\":\"버스는 그룹 B를 내려주고 즉시 돌아와서 그룹 A를 태우고 경기장까지 간다. 그룹 A가 P까지 걷는 데 걸린 시간과 그룹 B가 P에서 경기장까지 걷는 데 걸린 시간이 같으므로, 두 그룹은 동시에 도착한다.\"},{\"step 6\":\"결론적으로, 그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"},{\"answer\":\"그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"},{\"next_step\":\"step 3\"}]','2025-08-27 22:33:10.503682','uploads/2f620f9e-1451-44ee-a63e-cc538cbe845a.png',NULL,9,NULL,5),(132,'[{\"step 1\":\"문제에서 주어진 조건에 따라, 학교에서 경기장까지의 거리는 13km이다. P는 학교와 경기장 사이의 중간 지점이므로, P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 도달하는 데 걸리는 시간 t₁은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 버스를 타고 P까지 가는데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다. P에서 그룹 B는 걸어서 경기장까지 가야 한다.\"},{\"step 4\":\"그룹 B가 P에서 경기장까지 걷는 거리는 6.5km이고, 그룹 A가 P에서 경기장까지 버스를 타고 가는 거리는 6.5km이다. 그룹 A는 버스를 타고 50km/h로 이동한다.\"},{\"step 5\":\"그룹 B가 P에서 경기장까지 걷는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다. 그룹 A는 버스를 타고 6.5km를 이동하는 데 6.5km / 50km/h = 0.13시간이 걸린다.\"},{\"step 6\":\"그룹 A와 그룹 B는 동시에 경기장에 도착하므로, 그룹 A가 버스를 타고 이동한 거리와 그룹 B가 걸은 거리는 각각 6.5km이다.\"},{\"answer\":\"그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"}]','2025-08-27 22:36:14.385144','uploads/2f620f9e-1451-44ee-a63e-cc538cbe845a.png',NULL,9,NULL,5),(133,'[{\"step 1\":\"문제에서 주어진 조건에 따라, 학교에서 경기장까지의 거리는 13km이다. P는 학교와 경기장 사이의 중간 지점이므로, P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 그룹 B는 P에서 버스에서 내려 걷기 시작한다.\"},{\"step 3\":\"그룹 B가 P까지 버스를 타고 가는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 4\":\"그룹 A가 P까지 걷는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 5\":\"버스는 그룹 B를 내려주고 즉시 돌아와 그룹 A를 태운다. 그룹 A가 P까지 걷는 동안 버스는 왕복하여 그룹 A를 태우고 경기장까지 간다.\"},{\"step 6\":\"그룹 A는 P까지 6.5km를 걷고, 그룹 B는 P에서 경기장까지 6.5km를 걷는다.\"},{\"answer\":\"그룹 A는 6.5km를 걷고, 그룹 B는 6.5km를 걷는다.\"}]','2025-08-27 22:45:35.754150','uploads/2f620f9e-1451-44ee-a63e-cc538cbe845a.png',NULL,9,NULL,5),(134,'[{\"step 1\":\"문제를 이해한다. 그룹 A는 시속 5km로 걷고, 그룹 B는 시속 50km로 버스를 타고 이동한다. 두 그룹은 동시에 출발하며, 학교에서 경기장까지의 거리는 13km이다. 중간 지점 P에서 그룹 B는 버스에서 내려 걷기 시작하고, 버스는 즉시 돌아가 그룹 A를 태우고 경기장으로 간다. 두 그룹은 동시에 경기장에 도착한다.\"},{\"step 2\":\"각 그룹의 이동 시간을 계산한다. 그룹 A는 시속 5km로 13km를 걷기 때문에 13/5 = 2.6시간이 걸린다. 그룹 B는 시속 50km로 6.5km를 이동하는데 6.5/50 = 0.13시간이 걸린다. 그룹 B는 나머지 6.5km를 걷기 때문에 6.5/v 시간이 걸린다.\"},{\"step 3\":\"버스가 그룹 A를 태우고 경기장까지 가는 시간을 계산한다. 버스는 시속 50km로 6.5km를 이동하므로 6.5/50 = 0.13시간이 걸린다. 그룹 A가 버스를 타고 이동하는 시간은 6.5/50 = 0.13시간이다.\"},{\"step 4\":\"두 그룹이 동시에 도착하기 위해 그룹 B가 걷는 속도 v를 찾는다. 그룹 A의 총 이동 시간은 2.6시간이고, 그룹 B의 총 이동 시간은 0.13 + 6.5/v + 0.13시간이다. 이를 같게 하여 v를 구한다.\"},{\"step 5\":\"계산을 통해 그룹 B의 걷는 속도 v를 구하고, 각 그룹이 걸은 거리를 계산한다. 그룹 A는 13km를 걸었고, 그룹 B는 6.5km를 걸었다.\"},{\"answer\":\"그룹 A는 13km를 걸었고, 그룹 B는 6.5km를 걸었다.\"}]','2025-08-27 22:48:08.645600','uploads/2f620f9e-1451-44ee-a63e-cc538cbe845a.png',NULL,9,NULL,5),(165,'[{\"step 1\":\"A와 B 사이의 거리는 120km이다. 갑은 시속 50km로 A에서 B로 이동하고, 을은 시속 48km로 B에서 A로 이동한다.\"},{\"step 2\":\"각 기지국은 40km까지 전파를 송출할 수 있다. 따라서 A와 B에서 각각 40km 떨어진 지점까지는 방송을 들을 수 있다.\"},{\"step 3\":\"갑이 A에서 출발하여 40km 지점까지 도달하는 데 걸리는 시간은 40km / 50km/h = 0.8시간, 즉 48분이다.\"},{\"step 4\":\"을이 B에서 출발하여 40km 지점까지 도달하는 데 걸리는 시간은 40km / 48km/h ≈ 0.833시간, 즉 약 50분이다.\"},{\"step 5\":\"갑과 을이 동시에 출발하므로, 갑은 9시 48분에 방송을 들을 수 없고, 을은 9시 50분에 방송을 들을 수 없다.\"},{\"step 6\":\"따라서 방송을 들을 수 없는 시간대는 9시 48분부터 9시 50분까지이다.\"},{\"answer\":\"9시 48분부터 9시 50분까지\"}]','2025-08-28 03:48:44.822040','uploads/637afea2-2395-4868-9932-8a4a93e86826.png',NULL,9,NULL,12),(166,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 학교와 경기장 사이의 중간 지점이므로, P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 가는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 50km/h의 속도로 6.5km를 가므로, P까지 가는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 4\":\"그룹 B는 P에서 내려 걷기 시작하고, 버스는 즉시 돌아가 그룹 A를 태운다. 그룹 A가 P에 도착할 때까지 버스는 1.3시간 - 0.13시간 = 1.17시간 동안 이동할 수 있다.\"},{\"step 5\":\"버스는 1.17시간 동안 50km/h의 속도로 이동하므로, 1.17시간 * 50km/h = 58.5km를 이동할 수 있다. 하지만 실제로는 6.5km만 이동하면 된다. 따라서 버스는 그룹 A를 태우고 경기장까지 이동한다.\"},{\"step 6\":\"결국 그룹 A는 P까지 6.5km를 걷고, 그룹 B는 P에서 경기장까지 6.5km를 걷는다.\"},{\"answer\":\"그룹 A는 6.5km를 걷고, 그룹 B는 6.5km를 걷는다.\"}]','2025-08-28 03:49:25.414841','uploads/673afda9-3514-4d7e-a135-b208b7be7f7f.png',NULL,9,NULL,12),(167,'[{\"step 1\":\"A와 B를 간단히 정리한다. A = 2^2 = 4, B = 3^3 = 27\"},{\"step 2\":\"54를 소인수분해한다. 54 = 2 × 3^3\"},{\"step 3\":\"54를 A와 B로 표현한다. 54 = 2 × B\"},{\"step 4\":\"54^2를 계산한다. 54^2 = (2 × B)^2 = 2^2 × B^2 = A × B^2\"},{\"answer\":\"54^2 = A × B^2\"}]','2025-08-28 03:57:43.429931','uploads/5d90443d-6fe2-4982-9da8-8d6cf89450bd.png',NULL,3,NULL,12),(168,'[{\"step 1\":\"문제에서 갑과 을이 각각 A와 B에서 출발하여 서로 반대 방향으로 이동한다고 주어졌다. 갑은 시속 50km, 을은 시속 48km로 이동한다.\"},{\"step 2\":\"각 기지국은 40km까지 전파를 송출할 수 있으므로, A와 B에서 각각 40km 떨어진 지점까지는 방송을 들을 수 있다.\"},{\"step 3\":\"갑이 A에서 출발하여 40km 지점까지 도달하는 데 걸리는 시간은 40km / 50km/h = 0.8시간이다. 을이 B에서 출발하여 40km 지점까지 도달하는 데 걸리는 시간은 40km / 48km/h ≈ 0.833시간이다.\"},{\"step 4\":\"따라서 갑과 을이 각각 방송을 들을 수 없는 시간대는 0.8시간과 0.833시간 이후부터이다. 이 두 시간 중 더 긴 시간인 0.833시간 이후부터 방송을 들을 수 없다.\"},{\"answer\":\"갑과 을이 방송을 들을 수 없는 시간대는 출발 후 약 0.833시간 이후부터이다.\"}]','2025-08-28 03:58:12.153201','uploads/5cb0ffe0-3a00-4eb5-8cd5-c9c5cdf0b895.png',NULL,9,NULL,12),(169,'[{\"step 1\":\"문제에서 각 사람이 식초가 섞인 주스를 마실 확률을 구해야 한다. 총 4잔 중 1잔에 식초가 섞여 있다.\"},{\"step 2\":\"호동이 식초가 섞인 주스를 마실 확률은 4잔 중 1잔을 선택하는 것이므로 \\\\( \\\\frac{1}{4} \\\\)이다.\"},{\"step 3\":\"지원이 식초가 섞인 주스를 마실 확률은 호동이 식초가 섞인 주스를 마시지 않았을 경우에만 가능하다. 따라서 \\\\( \\\\frac{3}{4} \\\\times \\\\frac{1}{3} = \\\\frac{1}{4} \\\\)이다.\"},{\"step 4\":\"규현이 식초가 섞인 주스를 마실 확률은 호동과 지원이 식초가 섞인 주스를 마시지 않았을 경우에만 가능하다. 따라서 \\\\( \\\\frac{3}{4} \\\\times \\\\frac{2}{3} \\\\times \\\\frac{1}{2} = \\\\frac{1}{4} \\\\)이다.\"},{\"step 5\":\"마지막으로 민호가 식초가 섞인 주스를 마실 확률은 앞의 세 사람이 모두 식초가 섞인 주스를 마시지 않았을 경우에만 가능하다. 따라서 \\\\( \\\\frac{3}{4} \\\\times \\\\frac{2}{3} \\\\times \\\\frac{1}{2} \\\\times 1 = \\\\frac{1}{4} \\\\)이다.\"},{\"answer\":\"호동, 지원, 규현, 민호가 식초가 섞인 주스를 마실 확률은 각각 \\\\( \\\\frac{1}{4} \\\\)이다.\"}]','2025-08-28 04:00:05.161601','uploads/de8b58ca-e25f-4e24-902c-c3b2f01bc288.png',NULL,26,NULL,12),(170,'[{\"step 1\":\"주어진 값을 이해하자. A = 2^2이고 B = 3^3이다. 따라서 A = 4, B = 27이다.\"},{\"step 2\":\"54를 소인수분해하자. 54 = 2 × 3^3이다.\"},{\"step 3\":\"54^2를 계산하자. (2 × 3^3)^2 = 2^2 × (3^3)^2 = 2^2 × 3^6이다.\"},{\"step 4\":\"A와 B를 사용하여 54^2를 표현하자. A = 2^2이고 B = 3^3이므로, 54^2 = A × B^2이다.\"},{\"answer\":\"54^2 = A × B^2\"}]','2025-08-28 04:04:04.440489','uploads/d7366a3f-6dcb-4775-961a-35e27c096837.png',NULL,3,NULL,12),(171,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 중간 지점이므로, 학교에서 P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 가는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 버스를 타고 P까지 가는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 4\":\"그룹 B는 P에서 내려서 걷기 시작하고, 버스는 돌아가서 그룹 A를 태운다. 그룹 A가 P에 도착할 때까지 버스는 1.3시간 - 0.13시간 = 1.17시간 동안 이동할 수 있다.\"},{\"step 5\":\"버스는 1.17시간 동안 50km/h로 이동하므로, 1.17시간 * 50km/h = 58.5km를 이동할 수 있다. 하지만 실제로는 6.5km만 이동하고 돌아가야 하므로, 그룹 A를 태우고 경기장까지 가는 데 충분하다.\"},{\"step 6\":\"그룹 A는 P에서 경기장까지 6.5km를 버스로 이동하고, 그룹 B는 P에서 경기장까지 6.5km를 걷는다.\"},{\"answer\":\"그룹 A는 6.5km를 걷고, 그룹 B는 6.5km를 걸었다.\"}]','2025-08-28 04:04:29.114434','uploads/1517d3d8-ac79-4b1f-be91-685961a94877.png',NULL,9,NULL,12),(172,'[{\"step 1\":\"A와 B 사이의 거리는 120km이다. 갑은 시속 50km로 A에서 B로 이동하고, 을은 시속 48km로 B에서 A로 이동한다.\"},{\"step 2\":\"각 기지국은 40km까지 전파를 송출할 수 있다. 따라서 A 기지국의 전파 범위는 A에서 40km까지, B 기지국의 전파 범위는 B에서 40km까지이다.\"},{\"step 3\":\"A와 B 사이의 120km 중에서 전파가 닿지 않는 구간은 120km - 40km - 40km = 40km이다. 이 구간에서는 방송을 들을 수 없다.\"},{\"step 4\":\"갑과 을이 동시에 출발하여 이 40km 구간에 도달하는 시간을 계산한다. 갑은 시속 50km로 이동하므로 40km를 가는데 40/50 시간, 을은 시속 48km로 이동하므로 40km를 가는데 40/48 시간이 걸린다.\"},{\"step 5\":\"갑이 전파가 닿지 않는 구간에 도달하는 시간은 40/50 = 0.8시간, 을이 도달하는 시간은 40/48 ≈ 0.833시간이다. 따라서 두 사람이 동시에 전파가 닿지 않는 구간에 있는 시간은 9시 48분부터 9시 50분까지이다.\"},{\"answer\":\"방송을 들을 수 없는 시간대는 9시 48분부터 9시 50분까지이다.\"}]','2025-08-28 04:04:49.872229','uploads/380be65d-ee09-427b-9062-6834a65231bd.png',NULL,9,NULL,12),(173,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 그 중간 지점이므로, P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 가는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 버스를 타고 P까지 가는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 4\":\"그룹 B는 P에서 내려서 걸어가고, 버스는 돌아와서 그룹 A를 태운다. 그룹 A가 버스를 타고 남은 6.5km를 가는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 5\":\"그룹 A는 총 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다. 따라서 두 그룹 모두 6.5km를 걸었다.\"},{\"answer\":\"각 그룹은 6.5km를 걸었다.\"}]','2025-08-28 04:05:35.356270','uploads/073b8bfa-9620-4209-8b84-fe3e8cf2a6aa.png',NULL,9,NULL,12),(174,'[{\"step 1\":\"A와 B 사이의 거리는 120km이다. 갑은 시속 50km로 A에서 B로 이동하고, 을은 시속 48km로 B에서 A로 이동한다.\"},{\"step 2\":\"각 기지국은 40km까지 전파를 송출할 수 있다. 따라서 A 기지국의 전파 범위는 A에서 40km까지, B 기지국의 전파 범위는 B에서 40km까지이다.\"},{\"step 3\":\"A와 B 사이의 거리가 120km이므로, 두 전파 범위가 겹치지 않는다. 따라서 갑과 을이 전파를 받을 수 없는 구간은 A에서 40km를 제외한 80km 구간이다.\"},{\"step 4\":\"갑은 시속 50km로 이동하므로 80km 구간을 80/50 = 1.6시간 동안 전파를 받을 수 없다. 을은 시속 48km로 이동하므로 80/48 ≈ 1.67시간 동안 전파를 받을 수 없다.\"},{\"answer\":\"갑은 약 1.6시간, 을은 약 1.67시간 동안 전파를 받을 수 없다.\"}]','2025-08-28 04:06:17.978628','uploads/2fce49af-30f5-4ce9-87d4-8f0c1a1a810a.png',NULL,10,NULL,12),(175,'[{\"step 1\":\"문제에서 A=2^2, B=3^3이라고 주어졌다. 이를 이용해 54^2를 A와 B로 표현해야 한다.\"},{\"step 2\":\"54는 2와 3의 거듭제곱으로 표현할 수 있다. 54 = 2 * 3^3이다.\"},{\"step 3\":\"54^2 = (2 * 3^3)^2 = 2^2 * (3^3)^2 = 2^2 * 3^6이다.\"},{\"step 4\":\"A = 2^2이고, B = 3^3이므로, 54^2 = A * B^2로 표현할 수 있다.\"},{\"answer\":\"54^2 = A * B^2\"}]','2025-08-28 04:09:23.163965','uploads/48b06176-a816-4582-837b-dee4efedc6ce.png',NULL,6,NULL,12),(177,'[{\"step 1\":\"문제에서 주어진 조건을 정리합니다. 삼각형 ABC는 직각삼각형이며, C에서 직각입니다. O는 BC의 중점입니다. ∠OAB : ∠OAC = 2:1입니다.\"},{\"step 2\":\"∠OAB를 2x, ∠OAC를 x로 두고, 삼각형 AOB와 AOC의 성질을 이용해 각도를 구합니다. ∠BOA는 ∠OAB와 ∠OAC의 합입니다.\"},{\"step 3\":\"삼각형 AOB와 AOC는 각각 ∠OAB와 ∠OAC를 포함하고 있으며, O는 BC의 중점이므로 대칭성을 이용할 수 있습니다. ∠BOA = ∠OAB + ∠OAC = 2x + x = 3x입니다.\"},{\"step 4\":\"삼각형 ABC에서 ∠BAC = 90° - (2x + x) = 90° - 3x입니다. ∠BOA는 ∠BAC와 동일한 각도입니다.\"},{\"step 5\":\"주어진 조건에 따라 ∠BOA = 90°입니다. 따라서 ∠BOA의 크기는 90°입니다.\"},{\"answer\":\"90°\"}]','2025-08-28 14:33:30.092173','uploads/ce5bd73f-5ca0-4712-8a6b-97bf3598b6c0.png',NULL,15,NULL,12),(178,'[{\"step 1\":\"문제에 따르면, 삼각형 ABC는 직각삼각형이고, O는 BC의 중점이다. ∠OAB : ∠OAC = 2:1이라는 조건이 주어졌다.\"},{\"step 2\":\"∠OAB와 ∠OAC의 비율이 2:1이므로, ∠OAB = 2x, ∠OAC = x로 둘 수 있다.\"},{\"step 3\":\"삼각형 AOB와 AOC는 각각 이등변삼각형이므로, ∠BOA = ∠OAB = 2x, ∠COA = ∠OAC = x이다.\"},{\"step 4\":\"삼각형 AOC에서 ∠AOC = 180° - 2x - x = 180° - 3x이다. 삼각형 AOB에서 ∠AOB = 180° - 2x - 2x = 180° - 4x이다.\"},{\"step 5\":\"∠BOA는 ∠AOB와 ∠AOC의 차이이므로, ∠BOA = (180° - 4x) - (180° - 3x) = x이다.\"},{\"answer\":\"∠BOA의 크기는 x이다.\"}]','2025-08-28 14:35:26.891242','uploads/ce5bd73f-5ca0-4712-8a6b-97bf3598b6c0.png',NULL,15,NULL,12),(179,'[{\"step 1\":\"주어진 식 \\\\(x^2 - y^2 + x + y\\\\)를 인수분해한다. \\\\(x^2 - y^2\\\\)는 두 제곱의 차이로 \\\\((x + y)(x - y)\\\\)로 인수분해할 수 있다.\"},{\"step 2\":\"인수분해된 식을 다시 쓰면 \\\\((x + y)(x - y) + x + y\\\\)가 된다. 여기서 \\\\(x + y\\\\)를 공통 인수로 묶으면 \\\\((x + y)((x - y) + 1)\\\\)가 된다.\"},{\"step 3\":\"따라서 주어진 식은 \\\\((x + y)(x - y + 1)\\\\)로 인수분해된다. 이제 각 선택지를 확인하여 이 식의 인수가 아닌 것을 찾는다.\"},{\"step 4\":\"선택지 ① 1은 모든 수의 인수이므로 인수이다. 선택지 ② \\\\(x + y\\\\)는 인수이다. 선택지 ③ \\\\(x - y + 1\\\\)도 인수이다. 선택지 ④ \\\\(x - y - 1\\\\)은 인수에 포함되지 않는다. 선택지 ⑤ \\\\((x + y)(x - y + 1)\\\\)은 전체 식과 동일하므로 인수이다.\"},{\"step 5\":\"따라서 \\\\(x - y - 1\\\\)은 주어진 식의 인수가 아니다.\"},{\"answer\":\"④ \\\\(x - y - 1\\\\)\"}]','2025-08-28 15:04:09.058944','uploads/e2f5ca72-d0ae-4e86-b875-5406bcf88ada.png',NULL,8,NULL,13),(180,'[{\"step 1\":\"오렌지 주스 4잔 중 1잔에 식초가 섞여 있다. 호동, 지원, 규현, 민호가 순서대로 잔을 선택한다.\"},{\"step 2\":\"호동이 식초가 섞인 주스를 마실 확률은 1/4이다. 이는 4잔 중 1잔을 선택할 때 식초가 섞인 잔을 고를 확률이다.\"},{\"step 3\":\"호동이 식초가 섞인 주스를 마시지 않았을 경우, 지원이 식초가 섞인 주스를 마실 확률은 1/3이다. 이는 남은 3잔 중 1잔을 선택할 때 식초가 섞인 잔을 고를 확률이다.\"},{\"step 4\":\"마찬가지로, 규현이 식초가 섞인 주스를 마실 확률은 1/2이다. 이는 남은 2잔 중 1잔을 선택할 때 식초가 섞인 잔을 고를 확률이다.\"},{\"step 5\":\"마지막으로, 민호가 식초가 섞인 주스를 마실 확률은 1이다. 이는 남은 1잔이 식초가 섞인 잔이기 때문이다.\"},{\"answer\":\"호동, 지원, 규현, 민호가 식초가 섞인 주스를 마실 확률은 각각 1/4, 1/3, 1/2, 1이다.\"}]','2025-08-28 15:05:34.798090','uploads/a1a1bf71-15f9-4735-a13c-2061fa8184c1.png',NULL,26,NULL,13),(181,'[{\"step 1\":\"A와 B 사이의 거리는 120km이다. 갑은 시속 50km로 A에서 B로 이동하고, 을은 시속 48km로 B에서 A로 이동한다.\"},{\"step 2\":\"각 기지국은 40km까지 전파를 송출할 수 있다. 따라서 A 기지국의 전파 범위는 A에서 40km까지, B 기지국의 전파 범위는 B에서 40km까지이다.\"},{\"step 3\":\"A와 B 사이의 전파가 닿지 않는 구간은 120km - 40km - 40km = 40km이다. 이 구간에서는 방송을 들을 수 없다.\"},{\"step 4\":\"갑과 을이 동시에 출발하여 이 40km 구간에 도달하는 시간을 계산한다. 갑은 시속 50km로 이동하므로 40km까지 40/50 시간, 을은 시속 48km로 이동하므로 40km까지 40/48 시간이 걸린다.\"},{\"step 5\":\"갑이 40km 구간에 도달하는 시간은 0.8시간, 을이 40km 구간에 도달하는 시간은 약 0.833시간이다. 따라서 두 사람이 동시에 방송을 들을 수 없는 시간대는 9시 48분부터 약 9시 50분까지이다.\"},{\"answer\":\"9시 48분부터 약 9시 50분까지 방송을 들을 수 없다.\"}]','2025-08-28 15:06:33.323397','uploads/cb5a0637-0287-4928-bf23-bcb184dc12c4.png',NULL,9,NULL,13),(182,'[{\"step 1\":\"문제에서 그룹 A와 B가 동시에 출발하여 13km 떨어진 경기장으로 이동한다. 그룹 A는 시속 5km로 걷고, 그룹 B는 시속 50km로 버스를 타고 간다. 중간 지점 P에서 그룹 B는 버스에서 내려 걷기 시작하고, 버스는 A를 태우러 돌아간다. 두 그룹은 동시에 도착한다.\"},{\"step 2\":\"중간 지점 P는 13km의 절반인 6.5km 지점이다. 그룹 B는 6.5km를 버스로 이동하고, 나머지 6.5km를 걷는다. 그룹 A는 처음부터 끝까지 걷는다.\"},{\"step 3\":\"그룹 B가 버스를 타고 6.5km를 이동하는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다. 나머지 6.5km를 걷는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다. 따라서 그룹 B의 총 이동 시간은 0.13 + 1.3 = 1.43시간이다.\"},{\"step 4\":\"그룹 A는 13km를 시속 5km로 걷는다. 따라서 그룹 A의 총 이동 시간은 13km / 5km/h = 2.6시간이다. 하지만 두 그룹이 동시에 도착해야 하므로, 버스가 그룹 A를 태우고 나머지 거리를 이동하는 시간을 고려해야 한다.\"},{\"step 5\":\"버스가 그룹 A를 태우러 돌아가는 시간과 그룹 A가 버스를 타고 이동하는 시간을 계산하여 두 그룹이 동시에 도착하도록 조정한다. 이 과정에서 그룹 A가 걷는 거리와 버스를 타고 이동하는 거리를 구한다.\"},{\"answer\":\"그룹 A는 6.5km를 걷고, 나머지 6.5km를 버스를 타고 이동한다. 그룹 B는 6.5km를 버스로 이동하고, 나머지 6.5km를 걷는다.\"}]','2025-08-28 15:07:09.679640','uploads/acb7ca6e-7f1c-4ec1-a475-924f00ef1edc.png',NULL,9,NULL,13),(183,'[{\"step 1\":\"문제에서 주어진 정보를 이해한다. 삼각형 ABC에서 O는 BC의 중점이며, ∠OAB : ∠OAC = 2:1이다. ∠BOA의 크기를 구해야 한다.\"},{\"step 2\":\"∠OAB와 ∠OAC의 비율이 2:1이므로, ∠OAB = 2x, ∠OAC = x로 설정한다. 따라서 ∠BAC = 3x가 된다.\"},{\"step 3\":\"O가 BC의 중점이므로 OB = OC이다. 삼각형 AOB와 AOC는 OA를 공유하고, OB = OC이므로, ∠BOA와 ∠COA는 같다.\"},{\"step 4\":\"∠BOA와 ∠COA가 같고, ∠BAC = 3x이므로, ∠BOA = ∠COA = 1.5x가 된다. 따라서 ∠BOA = 1.5x이다.\"},{\"step 5\":\"∠OAB : ∠OAC = 2:1이므로, ∠BOA = 60도이다. 이는 삼각형의 내각의 합이 180도임을 이용하여 계산할 수 있다.\"},{\"answer\":\"∠BOA = 60도\"}]','2025-08-28 15:09:57.306255','uploads/de4763a7-907d-4cac-954c-cf247d38aa62.png',NULL,15,NULL,13),(184,'[{\"step 1\":\"주어진 정보를 이해한다. 삼각형 ABC는 직각삼각형이며, O는 BC의 중점이다. ∠OAB : ∠OAC = 2:1이다.\"},{\"step 2\":\"∠OAB와 ∠OAC의 비율을 이용하여 각을 설정한다. ∠OAB = 2x, ∠OAC = x로 두고, 이 두 각이 AO를 공유하는 인접각임을 확인한다.\"},{\"step 3\":\"O가 BC의 중점이므로 BO = OC이다. 이 정보를 이용하여 삼각형 ABO와 ACO의 성질을 분석한다.\"},{\"step 4\":\"삼각형 ABO와 ACO에서 AO를 기준으로 대칭성을 고려하여 ∠BOA를 구한다. ∠BOA는 ∠OAB와 ∠OAC의 합이므로, ∠BOA = 2x + x = 3x이다.\"},{\"step 5\":\"∠OAB : ∠OAC = 2:1이므로, 2x + x = 3x = 90°가 되어야 한다. 따라서 x = 30°이다. 그러므로 ∠BOA = 3x = 90°이다.\"},{\"answer\":\"90°\"}]','2025-08-28 15:12:21.884199','uploads/897b2e56-145f-4ea7-9c69-0290b366d45a.png',NULL,15,NULL,13),(185,'[{\"step 1\":\"90의 모든 약수를 찾는다. 90은 1, 2, 3, 5, 6, 9, 10, 15, 18, 30, 45, 90의 약수를 가진다.\"},{\"step 2\":\"이 약수들 중에서 가장 큰 값을 찾는다.\"},{\"step 3\":\"가장 큰 약수는 90 자신이다.\"},{\"answer\":\"90\"}]','2025-08-28 15:12:33.832917','uploads/7f5883b9-4c10-4b6e-80b1-b00382d120ea.png',NULL,1,NULL,13),(186,'[{\"step 1\":\"주어진 삼각형의 세 변의 길이는 m^2+4, 4m, m^2-4이다. 이 삼각형이 직각삼각형인지 확인하기 위해 피타고라스 정리를 사용한다.\"},{\"step 2\":\"피타고라스 정리에 따르면, 직각삼각형의 경우 빗변의 제곱은 다른 두 변의 제곱의 합과 같다. 여기서 m^2+4가 빗변이라고 가정한다.\"},{\"step 3\":\"m^2+4의 제곱은 (m^2+4)^2 = m^4 + 8m^2 + 16이다. 다른 두 변의 제곱의 합은 (4m)^2 + (m^2-4)^2 = 16m^2 + (m^4 - 8m^2 + 16)이다.\"},{\"step 4\":\"두 변의 제곱의 합은 m^4 + 8m^2 + 16으로, 이는 빗변의 제곱과 같다. 따라서 이 삼각형은 직각삼각형이다.\"},{\"answer\":\"주어진 삼각형은 직각삼각형이다.\"}]','2025-08-28 15:15:51.341052','uploads/0cdec9fc-3362-45cb-ae71-5030c7c87f1c.png',NULL,20,NULL,13),(191,'[{\"step 1\":\"주어진 식 \\\\(x^2 - y^2 + x + y\\\\)을 인수분해한다. \\\\(x^2 - y^2\\\\)는 \\\\((x+y)(x-y)\\\\)로 인수분해할 수 있다.\"},{\"step 2\":\"식 \\\\(x^2 - y^2 + x + y\\\\)는 \\\\((x+y)(x-y) + x + y\\\\)로 쓸 수 있다. \\\\(x+y\\\\)를 공통 인수로 묶으면 \\\\((x+y)((x-y)+1)\\\\)가 된다.\"},{\"step 3\":\"따라서 \\\\(x^2 - y^2 + x + y\\\\)는 \\\\((x+y)(x-y+1)\\\\)로 인수분해된다.\"},{\"step 4\":\"주어진 선택지 중에서 \\\\((x+y)(x-y+1)\\\\)는 이미 인수로 포함되어 있다. 따라서 \\\\(x-y-1\\\\)이 인수가 아니다.\"},{\"answer\":\"④ \\\\(x - y - 1\\\\)\"}]','2025-08-28 18:40:55.423719','uploads/d9707a0e-6481-4acd-9818-ef7daf6c116c.png',NULL,8,NULL,12),(192,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 중간 지점이므로, 학교에서 P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 도달하는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 50km/h의 속도로 6.5km를 이동하므로, P까지 도달하는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 4\":\"그룹 B는 P에서 내려 걷기 시작하고, 버스는 즉시 돌아가 그룹 A를 태운다. 그룹 A가 P에 도착할 때까지 버스는 1.3시간 동안 이동할 수 있다.\"},{\"step 5\":\"버스는 1.3시간 동안 50km/h의 속도로 이동하므로, 1.3시간 * 50km/h = 65km를 이동할 수 있다. 하지만 실제로는 6.5km만 이동하면 되므로, 버스는 충분히 그룹 A를 태우고 경기장까지 갈 수 있다.\"},{\"step 6\":\"그룹 A는 P까지 6.5km를 걸었고, 그룹 B는 P에서 경기장까지 6.5km를 걸었다. 따라서 두 그룹 모두 6.5km를 걸었다.\"},{\"answer\":\"각 그룹은 6.5km를 걸었다.\"}]','2025-08-28 20:13:39.322710','uploads/12c9bcac-d8f9-4fa3-b626-6ef22f478df8.png',NULL,9,NULL,12),(193,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 중간 지점이므로, P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 가는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 50km/h의 속도로 6.5km를 가므로, P까지 가는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 4\":\"그룹 B는 P에서 내려 걷기 시작하고, 버스는 그룹 A를 태우러 돌아간다. 그룹 A는 버스를 타고 남은 6.5km를 간다.\"},{\"step 5\":\"그룹 A가 버스를 타고 6.5km를 가는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다. 따라서 그룹 A와 그룹 B는 동시에 경기장에 도착한다.\"},{\"step 6\":\"그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"},{\"answer\":\"그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"}]','2025-08-28 20:14:23.305971','uploads/0d3d1a53-6cbc-4671-b77c-d7088a419594.png',NULL,9,NULL,12),(194,'[{\"step 1\":\"문제 이해하기: 두 그룹 A와 B가 학교에서 13km 떨어진 경기장으로 이동한다. 그룹 A는 시속 5km로 걷고, 그룹 B는 시속 50km로 버스를 타고 이동한다. 중간 지점 P에서 그룹 B는 버스에서 내려 시속 2km로 걷는다. 버스는 즉시 돌아와 그룹 A를 태우고 경기장으로 간다. 두 그룹은 동시에 도착한다. 각 그룹이 걸은 거리를 구하라.\"},{\"step 2\":\"그룹 A의 이동 시간 계산: 그룹 A는 13km를 시속 5km로 걷는다. 따라서 이동 시간 t는 13/5 = 2.6시간이다.\"},{\"step 3\":\"그룹 B의 이동 시간 계산: 그룹 B는 6.5km를 시속 50km로 버스를 타고 이동한 후, 6.5km를 시속 2km로 걷는다. 버스 이동 시간은 6.5/50 = 0.13시간, 걷는 시간은 6.5/2 = 3.25시간이다. 총 이동 시간은 0.13 + 3.25 = 3.38시간이다.\"},{\"step 4\":\"버스가 그룹 A를 태우고 이동하는 시간 고려: 그룹 A가 버스를 타고 이동하는 시간을 고려하여 두 그룹이 동시에 도착하도록 조정한다. 그룹 A가 버스를 타고 이동한 거리를 계산하여 두 그룹의 도착 시간을 맞춘다.\"},{\"step 5\":\"두 그룹의 도착 시간 일치시키기: 그룹 A가 버스를 타고 이동한 거리와 시간을 조정하여 두 그룹이 동시에 도착하도록 한다. 이를 통해 각 그룹이 걸은 거리를 정확히 계산한다.\"},{\"answer\":\"그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"}]','2025-08-28 20:14:36.777148','uploads/42d64d29-b3a5-4a0d-b780-0aef5f596e5b.png',NULL,9,NULL,12),(195,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 그 중간 지점이므로, 학교에서 P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 가는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 50km/h의 속도로 6.5km를 가므로, P까지 가는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 4\":\"그룹 B는 P에서 내려서 걷기 시작하고, 버스는 그룹 A를 태우러 돌아간다. 그룹 A가 P에 도착할 때까지 버스는 1.3시간 동안 이동할 수 있다.\"},{\"step 5\":\"버스는 그룹 A를 태우고 경기장까지 가는데, 그룹 A가 P에 도착한 후 버스를 타고 경기장까지 가는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 6\":\"따라서 그룹 A는 6.5km를 걷고, 그룹 B는 6.5km를 걷는다. 두 그룹 모두 6.5km를 걸었다.\"},{\"answer\":\"그룹 A와 그룹 B는 각각 6.5km를 걸었다.\"}]','2025-09-28 19:03:50.072495','uploads/75143be1-26b7-4c75-a324-39da5ef8877b.png',NULL,9,NULL,5),(196,'[{\"step 1\":\"문제를 이해하자. 선분 AB가 있고, M은 그 선분의 중점이다. AB의 길이는 8cm이다. 우리는 AM의 길이를 찾아야 한다.\"},{\"step 2\":\"중점의 성질을 적용하자. M이 중점이므로 AM은 AB의 절반이다.\"},{\"step 3\":\"계산을 통해 AM의 길이를 구하자. AM = (1/2) * AB = (1/2) * 8cm = 4cm.\"},{\"answer\":\"4cm\"}]','2025-09-28 23:49:52.869772','uploads/09f8ac30-7bd8-41e3-976f-5ee3b8dc9fe0.png',NULL,15,NULL,12),(197,'[{\"step 1\":\"문제는 1부터 12까지의 숫자가 적힌 공 중에서 숫자가 3의 배수이거나 10의 약수인 공의 개수를 찾는 것이다.\"},{\"step 2\":\"1부터 12까지의 숫자 중 3의 배수를 찾는다. 3의 배수는 {3, 6, 9, 12}이다.\"},{\"step 3\":\"1부터 12까지의 숫자 중 10의 약수를 찾는다. 10의 약수는 {1, 2, 5, 10}이지만, 1부터 12까지의 범위 내에서는 {1, 2, 5, 10}이다.\"},{\"step 4\":\"3의 배수 집합 {3, 6, 9, 12}와 10의 약수 집합 {1, 2, 5, 10}의 합집합을 구한다. 합집합은 {1, 2, 3, 5, 6, 9, 10, 12}이다.\"},{\"step 5\":\"합집합의 원소 개수를 센다. 총 8개의 숫자가 있다.\"},{\"answer\":\"8\"}]','2025-09-29 00:12:36.867060','uploads/0dbac844-f47c-426a-b229-e4b959ac24de.png',NULL,1,NULL,12),(198,'[{\"step 1\":\"주어진 식은 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>이다. 이 식에서 같은 루트를 가진 항들을 더하고 빼야 한다.\"},{\"step 2\":\"먼저 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>와 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>를 더하면 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>가 된다.\"},{\"step 3\":\"이제 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>에서 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>를 빼면 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>가 된다.\"},{\"answer\":\"2\\\\sqrt{2}\"}]','2025-09-29 01:38:08.136353','uploads/75bf8859-4bf0-4aa0-9bcd-2f88630f1865.png',NULL,5,NULL,12),(199,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2는 (5x)^2로 표현할 수 있고, 1은 1^2로 표현할 수 있다. 따라서 중간항 -10x가 2ab 형태인지 확인한다.\"},{\"step 3\":\"중간항 -10x는 -2 * 5x * 1로 표현할 수 있다. 따라서 이 다항식은 (5x - 1)^2의 완전제곱식이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 01:40:16.589264','uploads/08ac2a6d-1110-4123-919c-16240177379e.png',NULL,8,NULL,12),(200,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x)^2 - 2*5x*1 + 1^2의 형태로, 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 02:05:16.744854','uploads/86353c99-da20-4bbd-91ef-7d7c6b7f7dc6.png',NULL,8,NULL,12),(201,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 중점 M에서 선분 AB를 두 개의 같은 길이로 나누므로, |AM| = |MB| = 8cm / 2이다.\"},{\"step 3\":\"계산을 통해 |AM| = 4cm임을 알 수 있다.\"},{\"answer\":\"4cm\"}]','2025-09-29 02:20:54.737310','uploads/9849e03f-0a04-43ff-b1ce-9fbf34d3b4a9.png',NULL,15,NULL,12),(202,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x)^2 - 2*5x*1 + 1^2의 형태로, 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 03:20:33.454451','uploads/e2fcf9ce-3a28-470d-911a-5e8d1254b625.png',NULL,8,NULL,12),(203,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x - 1)(5x - 1)로 인수분해된다.\"},{\"step 3\":\"따라서, 주어진 다항식의 인수분해 결과는 (5x - 1)^2이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 03:21:41.823327','uploads/e2fcf9ce-3a28-470d-911a-5e8d1254b625.png',NULL,8,NULL,12),(204,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x)^2 - 2*5x*1 + 1^2의 형태로 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 03:22:05.929500','uploads/efd9cac5-3a66-4d1d-bedf-39b6107c18c9.png',NULL,8,NULL,12),(205,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x)^2 - 2*5x*1 + 1^2의 형태로, 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 03:23:11.687211','uploads/efd9cac5-3a66-4d1d-bedf-39b6107c18c9.png',NULL,8,NULL,12),(206,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변환할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2는 (5x)^2로 표현할 수 있고, 1은 1^2로 표현할 수 있다. 따라서 중간 항 -10x가 2ab 형태인지 확인한다.\"},{\"step 3\":\"중간 항 -10x는 -2 * 5x * 1로 표현할 수 있다. 따라서 이 다항식은 (5x - 1)^2의 완전제곱식이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 03:23:25.142242','uploads/fe129963-fd14-4122-b799-d105e9d2c13f.png',NULL,8,NULL,12),(207,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x)^2 - 2*5x*1 + 1^2의 형태로, 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 03:25:43.401271','uploads/a718546e-d80e-4b0f-bcac-370a8c63620d.png',NULL,8,NULL,12),(208,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2는 (5x)^2로 표현할 수 있고, 1은 1^2로 표현할 수 있다. 따라서 중간 항 -10x가 2ab 형태인지 확인한다.\"},{\"step 3\":\"중간 항 -10x는 -2 * 5x * 1로 표현할 수 있다. 따라서 이 다항식은 (5x - 1)^2의 완전제곱식이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 03:27:24.065313','uploads/65c20a12-0097-4848-8c9b-f0f488204243.png',NULL,8,NULL,12),(209,'[{\"step 1\":\"문제에서 주어진 정보를 확인한다. 선분 AB의 길이는 8cm이고, M은 선분 AB의 중점이다.\"},{\"step 2\":\"중점의 정의에 따라, M은 선분 AB를 두 개의 같은 길이로 나눈다. 따라서 |AM| = |MB|이다.\"},{\"step 3\":\"선분 AB의 전체 길이가 8cm이므로, |AM|과 |MB|는 각각 8cm를 반으로 나눈 값이다.\"},{\"step 4\":\"따라서 |AM|의 길이는 8cm ÷ 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 03:29:00.356744','uploads/5cdf712a-101b-4ff4-85a8-31dbe06f36bd.png',NULL,15,NULL,12),(210,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합치면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 03:30:56.463448','uploads/a2cbd741-afea-4fd8-b3fe-e912b6af8c46.png',NULL,1,NULL,12),(211,'[{\"step 1\":\"문제에서 주어진 정보를 확인한다. 선분 AB의 길이는 8cm이고, M은 선분 AB의 중점이다.\"},{\"step 2\":\"중점의 성질을 이해한다. 중점 M은 선분 AB를 두 개의 같은 길이로 나눈다. 즉, |AM| = |MB|이다.\"},{\"step 3\":\"선분 AB의 길이를 반으로 나누어 |AM|의 길이를 계산한다. |AM| = |AB| / 2 = 8cm / 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 03:32:15.930613','uploads/1d8419b3-2405-46f0-95d8-d5cdcbea3d96.png',NULL,15,NULL,12),(212,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"3의 배수이거나 10의 약수인 숫자를 모두 모으면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 03:34:43.284431','uploads/919fcc08-04f6-48bf-97f9-b666547faf0f.png',NULL,1,NULL,12),(213,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 03:46:45.514577','uploads/eafd4452-ebbe-4e24-8491-a9cc607c46e7.png',NULL,1,NULL,12),(214,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"3의 배수이거나 10의 약수인 숫자를 모두 합치면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"중복을 제거한 후, 총 8개의 숫자가 있다.\"},{\"answer\":\"8\"}]','2025-09-29 03:48:50.374966','uploads/e4893688-259a-4e56-bfd4-6ec78e028244.png',NULL,1,NULL,12),(215,'[{\"step 1\":\"문제를 이해하자. 선분 AB가 있고, M은 그 선분의 중점이다. |AB| = 8cm일 때, |AM|의 길이를 구하라.\"},{\"step 2\":\"중점의 개념을 사용하자. 중점은 선분을 두 개의 같은 길이로 나눈다. 따라서, AM = MB = |AB| / 2이다.\"},{\"step 3\":\"주어진 값을 대입하자. |AM| = 8cm / 2 = 4cm이다.\"},{\"step 4\":\"결론적으로, |AM|의 길이는 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 03:52:08.045317','uploads/707a000a-2ca2-45a2-8a06-cab4bb52eef5.png',NULL,15,NULL,12),(216,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 중점 M에서 선분 AB를 두 개의 같은 길이로 나누므로, |AM| = |MB| = 8cm / 2이다.\"},{\"step 3\":\"계산을 통해 |AM| = 4cm임을 알 수 있다.\"},{\"answer\":\"4cm\"}]','2025-09-29 03:52:21.251078','uploads/707a000a-2ca2-45a2-8a06-cab4bb52eef5.png',NULL,15,NULL,12),(217,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 중점 M에 의해 |AM|과 |MB|는 각각 AB의 절반이다.\"},{\"step 3\":\"따라서 |AM| = |MB| = 8cm ÷ 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 03:53:45.856901','uploads/707a000a-2ca2-45a2-8a06-cab4bb52eef5.png',NULL,15,NULL,12),(218,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 03:56:42.619017','uploads/4c70d3ed-30e4-456c-8e36-344b375a8d20.png',NULL,1,NULL,12),(219,'[{\"step 1\":\"1부터 12까지의 숫자 중에서 3의 배수를 찾는다. 3, 6, 9, 12가 있다.\"},{\"step 2\":\"1부터 12까지의 숫자 중에서 10의 약수를 찾는다. 1, 2, 5, 10이 있다.\"},{\"step 3\":\"3의 배수이거나 10의 약수인 숫자를 모두 모은다. 1, 2, 3, 5, 6, 9, 10, 12가 있다.\"},{\"step 4\":\"중복을 제거한 후, 총 몇 개의 숫자가 있는지 센다. 총 8개의 숫자가 있다.\"},{\"answer\":\"8\"}]','2025-09-29 04:00:55.169772','uploads/ac1729a2-0c2d-4c2b-b4d0-2651f0fff903.png',NULL,1,NULL,12),(220,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"3의 배수이거나 10의 약수인 숫자를 모두 합치면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"중복 없이 숫자를 세면 총 8개의 숫자가 있다.\"},{\"answer\":\"8\"}]','2025-09-29 04:01:21.155830','uploads/ac1729a2-0c2d-4c2b-b4d0-2651f0fff903.png',NULL,1,NULL,12),(221,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 04:09:49.150731','uploads/199d3839-7120-4121-bd9b-8e865f63bd6e.png',NULL,1,NULL,12),(222,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"3의 배수이거나 10의 약수인 숫자를 모두 모으면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"이 숫자들의 개수를 세어보면 총 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 04:10:01.742013','uploads/199d3839-7120-4121-bd9b-8e865f63bd6e.png',NULL,1,NULL,12),(223,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"3의 배수이거나 10의 약수인 숫자를 모두 합치면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"중복된 숫자를 제거하고 나면 총 8개의 숫자가 있다.\"},{\"answer\":\"8\"}]','2025-09-29 04:11:08.619224','uploads/b366458d-fdc7-4465-823b-013ecf138f97.png',NULL,1,NULL,12),(224,'[{\"step 1\":\"문제에서 1부터 12까지의 숫자가 적힌 공이 각각 하나씩 들어 있는 상자가 있다. 이 중에서 숫자가 3의 배수이거나 10의 약수인 공의 개수를 찾아야 한다.\"},{\"step 2\":\"3의 배수인 숫자를 찾는다. 1부터 12까지의 숫자 중 3의 배수는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자를 찾는다. 1부터 12까지의 숫자 중 10의 약수는 1, 2, 5, 10이다.\"},{\"step 4\":\"3의 배수이거나 10의 약수인 숫자를 모두 합친다. 중복을 제거하면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 04:11:19.786659','uploads/b366458d-fdc7-4465-823b-013ecf138f97.png',NULL,1,NULL,12),(225,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 중점 M에 의해 |AM|과 |MB|는 각각 AB의 절반이다.\"},{\"step 3\":\"따라서 |AM| = |MB| = 8cm ÷ 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 04:11:31.346878','uploads/5acbc620-d9e3-4b8d-bc8f-46bedb7d1c5c.png',NULL,15,NULL,12),(226,'[{\"step 1\":\"문제에서 주어진 정보를 확인한다. 선분 AB의 길이는 8cm이고, M은 선분 AB의 중점이다.\"},{\"step 2\":\"중점의 정의에 따라, M은 선분 AB를 두 개의 같은 길이로 나눈다. 따라서 |AM| = |MB|이다.\"},{\"step 3\":\"선분 AB의 전체 길이가 8cm이므로, |AM| = |MB| = 8cm / 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 04:11:44.408356','uploads/5acbc620-d9e3-4b8d-bc8f-46bedb7d1c5c.png',NULL,15,NULL,12),(227,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"3의 배수와 10의 약수를 모두 포함하는 숫자는 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 04:16:38.339976','uploads/5df279cd-6c13-4430-a534-ccf9e6b27798.png',NULL,1,NULL,12),(228,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 04:17:01.255908','uploads/5df279cd-6c13-4430-a534-ccf9e6b27798.png',NULL,1,NULL,12),(229,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 중점 M에 의해 |AM|과 |MB|는 각각 AB의 절반이다.\"},{\"step 3\":\"따라서 |AM| = 8cm ÷ 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 04:17:16.423107','uploads/fecd20db-5550-457f-a161-4076d96428fa.png',NULL,15,NULL,12),(230,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 중점 M에서 선분을 두 개의 같은 길이로 나누므로, |AM| = |MB| = 8cm / 2이다.\"},{\"step 3\":\"계산을 통해 |AM| = 4cm임을 알 수 있다.\"},{\"answer\":\"4cm\"}]','2025-09-29 04:17:23.479448','uploads/fecd20db-5550-457f-a161-4076d96428fa.png',NULL,15,NULL,12),(231,'[{\"step 1\":\"문제에서 주어진 정보를 이해한다. 선분 AB의 길이는 8cm이고, M은 AB의 중점이다. 따라서 AM과 MB의 길이는 같다.\"},{\"step 2\":\"중점의 성질을 적용한다. 중점 M은 선분 AB를 두 개의 같은 길이로 나눈다. 따라서 AM = MB이다.\"},{\"step 3\":\"AM의 길이를 계산한다. 중점의 성질에 따라 AM의 길이는 AB의 절반이다. 따라서 |AM| = |AB| / 2이다.\"},{\"step 4\":\"주어진 값을 대입하여 계산한다. |AB| = 8cm이므로 |AM| = 8cm / 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 04:21:40.282514','uploads/768e2e2a-a2ab-455a-8753-c27127f613ce.png',NULL,15,NULL,12),(232,'[{\"step 1\":\"점 M이 선분 AB의 중점이므로, 선분 AB를 두 개의 같은 길이로 나눈다.\"},{\"step 2\":\"선분 AB의 전체 길이가 8cm이므로, 이를 반으로 나누어 각 부분의 길이를 구한다.\"},{\"step 3\":\"8cm를 2로 나누면, 각 부분의 길이는 4cm가 된다.\"},{\"answer\":\"4cm\"}]','2025-09-29 04:22:01.087199','uploads/768e2e2a-a2ab-455a-8753-c27127f613ce.png',NULL,15,NULL,12),(233,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변환할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변환할 수 있다. 이는 (5x)^2 - 2(5x)(1) + 1^2의 형태로, 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 04:22:22.847747','uploads/334ed9ce-4068-4b32-ab8c-58642d861f48.png',NULL,8,NULL,12),(234,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 04:24:06.849226','uploads/e046a5b5-16c5-44ff-9beb-475e7eaaf551.png',NULL,1,NULL,12),(235,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"3의 배수이거나 10의 약수인 숫자를 모두 합치면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"중복을 제거한 후, 총 8개의 숫자가 있다.\"},{\"answer\":\"8\"}]','2025-09-29 04:24:24.813588','uploads/e046a5b5-16c5-44ff-9beb-475e7eaaf551.png',NULL,1,NULL,12),(236,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x - 1)(5x - 1)로 인수분해된다.\"},{\"step 3\":\"따라서, 주어진 다항식 25x^2 - 10x + 1의 인수분해 결과는 (5x - 1)^2이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 04:24:45.278424','uploads/99dd14c9-a7bd-4c2b-b012-1f78bf255e90.png',NULL,8,NULL,12),(237,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식의 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x)^2 - 2*5x*1 + 1^2의 형태로, 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 04:27:43.971884','uploads/ce22be61-8e68-45a2-92d1-5c48ee54fdd6.png',NULL,8,NULL,12),(238,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x)^2 - 2*5x*1 + 1^2의 형태로, 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 04:27:52.078955','uploads/ce22be61-8e68-45a2-92d1-5c48ee54fdd6.png',NULL,8,NULL,12),(239,'[{\"step 1\":\"점 M이 선분 AB의 중점이라는 것을 확인한다. 이는 AM = MB를 의미한다.\"},{\"step 2\":\"선분 AB의 전체 길이가 8cm로 주어졌으므로, 이를 점 M에서 반으로 나눈다: |AM| = |AB| / 2 = 8cm / 2\"},{\"step 3\":\"나눗셈을 수행하여 |AM|의 길이를 구한다: |AM| = 4cm\"},{\"answer\":\"4cm\"}]','2025-09-29 04:28:18.849161','uploads/6355ff6e-3a6b-4097-9b0c-c70590db63f0.png',NULL,15,NULL,12),(240,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x)^2 - 2*5x*1 + 1^2의 형태로 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 04:29:10.036226','uploads/89f685bb-8eff-40c9-9bc5-da1292d4a216.png',NULL,8,NULL,12),(241,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식의 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x)^2 - 2*5x*1 + 1^2의 형태로 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 04:33:09.717607','uploads/158aae37-71f0-4497-ac6e-e41cd958dae4.png',NULL,8,NULL,12),(242,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"3의 배수이거나 10의 약수인 숫자를 모두 합치면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"이 숫자들의 개수를 세어보면 총 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 04:38:55.982931','uploads/9cf19c2a-f056-4b20-a3fc-95fb59e93e23.png',NULL,1,NULL,12),(243,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"3의 배수이거나 10의 약수인 숫자를 모두 합치면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"중복된 숫자를 제거하고 나면 총 8개의 숫자가 있다.\"},{\"answer\":\"8\"}]','2025-09-29 04:39:15.345672','uploads/9cf19c2a-f056-4b20-a3fc-95fb59e93e23.png',NULL,1,NULL,12),(244,'[{\"step 1\":\"주어진 정보를 이해하자. 선분 AB가 있고, M은 그 선분의 중점이다. |AB| = 8cm이다.\"},{\"step 2\":\"문제에서 요구하는 것을 파악하자. |AM|의 길이를 구해야 한다.\"},{\"step 3\":\"중점의 성질을 적용하자. M이 중점이므로 |AM| = |MB|이다.\"},{\"step 4\":\"각 선분의 길이를 계산하자. |AB| = 8cm이므로, |AM| = |MB| = 8cm / 2 = 4cm이다.\"},{\"answer\":\"|AM| = 4cm\"}]','2025-09-29 04:40:35.671531','uploads/cdcfae93-057a-453f-9eb5-0e7c909acdff.png',NULL,15,NULL,12),(245,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"3의 배수이거나 10의 약수인 숫자를 모두 합치면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"중복을 제거한 후, 총 8개의 숫자가 있다.\"},{\"answer\":\"8\"}]','2025-09-29 04:44:56.142661','uploads/29e78079-375b-4537-9d0d-a428b39bd596.png',NULL,1,NULL,12),(246,'[{\"step 1\":\"문제에서 1부터 12까지의 숫자가 적힌 공이 각각 하나씩 들어 있는 상자가 있다. 이 중에서 숫자가 3의 배수이거나 10의 약수인 공의 개수를 구해야 한다.\"},{\"step 2\":\"1부터 12까지의 숫자 중 3의 배수를 찾는다. 3, 6, 9, 12가 3의 배수이다.\"},{\"step 3\":\"1부터 12까지의 숫자 중 10의 약수를 찾는다. 1, 2, 5, 10이 10의 약수이다.\"},{\"step 4\":\"3의 배수이거나 10의 약수인 숫자를 모두 모은다. 중복을 제거하면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"이 숫자들의 개수를 센다. 총 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 04:47:40.910937','uploads/83d3fc87-4e20-4fe8-8ebc-2423f7ac966a.png',NULL,1,NULL,12),(247,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x)^2 - 2*5x*1 + 1^2의 형태로, 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 04:49:06.544826','uploads/a510f9ba-546c-4bc5-aa93-e4e9c8f4fc87.png',NULL,8,NULL,12),(248,'[{\"step 1\":\"점 M이 선분 AB의 중점이라는 것을 확인한다. 이는 M이 AB를 두 개의 같은 길이로 나눈다는 의미이다.\"},{\"step 2\":\"선분 AB의 전체 길이가 8cm이므로, 중점 M을 기준으로 두 부분으로 나누면 각 부분의 길이는 |AM| = |MB| = 8cm / 2 = 4cm이다.\"},{\"step 3\":\"따라서, |AM|의 길이는 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 04:55:16.514585','uploads/c22c4dbd-c08d-4a60-88cb-78a9db77db0b.png',NULL,15,NULL,12),(249,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2 형태로 변형할 수 있다. 이는 (5x)^2 - 2*5x*1 + 1^2의 형태로, 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 04:56:00.668754','uploads/0456a863-8179-4eb9-a3f1-ec4495382c5e.png',NULL,8,NULL,12),(250,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2는 (5x)^2로 표현할 수 있고, 1은 1^2로 표현할 수 있다. 따라서 중간항 -10x가 2ab 형태인지 확인한다.\"},{\"step 3\":\"중간항 -10x는 -2 * 5x * 1로 표현할 수 있다. 따라서 이 다항식은 (5x - 1)^2의 완전제곱식이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 04:57:19.612367','uploads/1ede6ad4-0c01-47d3-b6e2-33d0f956c911.png',NULL,8,NULL,12),(251,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x)^2 - 2*5x*1 + 1^2의 형태로, 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 04:57:29.351057','uploads/1ede6ad4-0c01-47d3-b6e2-33d0f956c911.png',NULL,8,NULL,12),(252,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2 형태로 변형할 수 있다. 이는 (5x)^2 - 2*5x*1 + 1^2의 형태로 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 04:57:39.051754','uploads/1ede6ad4-0c01-47d3-b6e2-33d0f956c911.png',NULL,8,NULL,12),(253,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x)^2 - 2*5x*1 + 1^2의 형태로, 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 04:58:52.970101','uploads/ed9cfe55-7e52-4836-8b1f-9abd6121bc5c.png',NULL,8,NULL,12),(254,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:00:39.643750','uploads/16c44a75-f209-41ce-8bc7-82cc0e4fb3fd.png',NULL,1,NULL,12),(255,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합치면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:01:01.340810','uploads/16c44a75-f209-41ce-8bc7-82cc0e4fb3fd.png',NULL,1,NULL,12),(256,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2는 (5x)^2로 표현할 수 있고, 1은 1^2로 표현할 수 있다. 따라서 중간항 -10x가 2ab 형태인지 확인한다.\"},{\"step 3\":\"중간항 -10x는 -2 * 5x * 1로 표현할 수 있다. 따라서 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 05:01:18.914648','uploads/363b26fb-a9e7-4647-bf01-d4066cb32d8a.png',NULL,8,NULL,12),(257,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:03:01.243644','uploads/1a2c5d17-28bd-4b53-a4ad-d87fb278e7ad.png',NULL,1,NULL,12),(258,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2는 (5x)^2로 표현할 수 있고, 1은 1^2로 표현할 수 있다. 따라서 중간항 -10x가 2ab 형태인지 확인한다.\"},{\"step 3\":\"중간항 -10x는 -2 * 5x * 1로 표현할 수 있다. 따라서 주어진 식은 (5x - 1)^2의 완전제곱식이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 05:03:50.761213','uploads/65d4ef41-93a1-44d6-96c8-5a1ee9d27e5b.png',NULL,8,NULL,12),(259,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해, 완전제곱식의 형태를 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 인수분해할 수 있다. 이는 (5x - 1)(5x - 1)로 표현된다.\"},{\"step 3\":\"따라서, 주어진 다항식의 인수분해 결과는 (5x - 1)^2이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 05:04:10.256442','uploads/65d4ef41-93a1-44d6-96c8-5a1ee9d27e5b.png',NULL,8,NULL,12),(260,'[{\"step 1\":\"문제에서 주어진 정보를 확인한다. 선분 AB의 길이는 8cm이고, M은 선분 AB의 중점이다.\"},{\"step 2\":\"중점의 정의에 따라, M은 선분 AB를 두 개의 같은 길이로 나눈다. 따라서 |AM| = |MB|이다.\"},{\"step 3\":\"선분 AB의 전체 길이가 8cm이므로, |AM|과 |MB|는 각각 8cm를 반으로 나눈 값이다.\"},{\"step 4\":\"따라서 |AM|의 길이는 8cm ÷ 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 05:04:30.453774','uploads/a6264949-73c7-406c-bfc1-3bec5bf5d771.png',NULL,15,NULL,12),(261,'[{\"step 1\":\"점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 따라서 |AM| + |MB| = 8cm이다.\"},{\"step 3\":\"중점의 정의에 따라 |AM| = |MB|이므로, 2|AM| = 8cm이다.\"},{\"step 4\":\"양변을 2로 나누어 |AM| = 4cm임을 알 수 있다.\"},{\"answer\":\"4cm\"}]','2025-09-29 05:08:33.097169','uploads/56908a22-72e5-4efd-a5aa-11986fc4bfbd.png',NULL,15,NULL,12),(262,'[{\"step 1\":\"점 M이 선분 AB의 중점이므로, |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다.\"},{\"step 3\":\"중점의 정의에 따라 |AM| = |MB| = |AB| / 2이다.\"},{\"step 4\":\"따라서 |AM| = 8cm / 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 05:08:50.487332','uploads/56908a22-72e5-4efd-a5aa-11986fc4bfbd.png',NULL,15,NULL,12),(263,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변환할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2는 (5x)^2로 표현할 수 있고, 1은 1^2로 표현할 수 있다. 따라서 중간항 -10x가 2ab 형태인지 확인한다.\"},{\"step 3\":\"중간항 -10x는 -2 * 5x * 1로 표현할 수 있다. 따라서 이 다항식은 (5x - 1)^2의 완전제곱식이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 05:10:48.255210','uploads/f9005e29-08cc-466a-9943-7061c3d1c915.png',NULL,8,NULL,12),(264,'[{\"step 1\":\"점 M이 선분 AB의 중점이므로, AM의 길이는 MB의 길이와 같다.\"},{\"step 2\":\"선분 AB의 전체 길이가 8cm이므로, AM과 MB의 길이는 각각 8cm를 반으로 나눈 값이다.\"},{\"step 3\":\"따라서 AM의 길이는 8cm ÷ 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 05:11:45.418969','uploads/70884c86-4cc6-4755-a031-e17e26db57e0.png',NULL,15,NULL,12),(265,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:14:27.511044','uploads/fe3536d5-33a9-49b4-98af-57150e5a569f.png',NULL,1,NULL,12),(266,'[{\"step 1\":\"점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다.\"},{\"step 3\":\"중점의 정의에 따라 |AM| = |MB| = |AB| / 2이다.\"},{\"step 4\":\"따라서 |AM| = 8cm / 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 05:15:00.396121','uploads/671b3745-b4cf-4d71-bade-fc1d57ae7f09.png',NULL,15,NULL,12),(267,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2는 (5x)^2로 표현할 수 있고, 1은 1^2로 표현할 수 있다. 따라서 중간 항 -10x가 2ab 형태인지 확인한다.\"},{\"step 3\":\"중간 항 -10x는 -2 * 5x * 1로 표현할 수 있다. 따라서 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 05:16:36.078840','uploads/4850c433-2e17-4908-a460-b649237e8ed3.png',NULL,8,NULL,12),(268,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:19:49.621374','uploads/5aec90c4-4834-471a-a862-5a21fb8cf90b.png',NULL,1,NULL,12),(269,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해한다.\"},{\"step 2\":\"이 다항식은 완전제곱식의 형태를 띠고 있다. (ax + b)^2 = a^2x^2 + 2abx + b^2 형태로 변환할 수 있다.\"},{\"step 3\":\"25x^2 - 10x + 1은 (5x - 1)^2로 인수분해된다. 이는 5x의 제곱에서 2배의 5x와 1의 곱을 뺀 후 1을 더한 형태이다.\"},{\"step 4\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 05:20:08.846543','uploads/31d6a184-467f-4f46-99ff-26bb7ec0bb6c.png',NULL,8,NULL,12),(270,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수는 3, 6, 9, 12이고, 10의 약수는 1, 2, 5, 10이다.\"},{\"step 3\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 4\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:20:16.590812','uploads/d65dc4a7-08f0-4199-9eb0-d7993d662ac6.png',NULL,1,NULL,12),(271,'[{\"step 1\":\"점 M이 선분 AB의 중점이라는 것을 확인한다. 중점이란 두 점 사이의 거리를 반으로 나누는 점을 의미한다.\"},{\"step 2\":\"주어진 조건에 따르면 |AB| = 8cm이다. 따라서 |AM|과 |MB|는 각각 |AB|의 절반이다.\"},{\"step 3\":\"계산을 통해 |AM|의 길이를 구한다. |AM| = |AB| / 2 = 8cm / 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 05:21:22.996132','uploads/49b7dcb4-fb7b-408b-90e3-e240896a1990.png',NULL,15,NULL,12),(272,'[{\"step 1\":\"문제에서 주어진 조건에 맞는 공의 번호를 찾기 위해, 1부터 12까지의 숫자 중에서 3의 배수이거나 10의 약수인 숫자를 찾아야 한다.\"},{\"step 2\":\"1부터 12까지의 숫자 중 3의 배수를 찾는다. 3의 배수는 3, 6, 9, 12이다.\"},{\"step 3\":\"1부터 12까지의 숫자 중 10의 약수를 찾는다. 10의 약수는 1, 2, 5, 10이지만, 10은 12보다 작지 않으므로 제외하고 1, 2, 5만 고려한다.\"},{\"step 4\":\"3의 배수와 10의 약수를 합쳐 중복을 제거한다. 3, 6, 9, 12와 1, 2, 5를 합치면 1, 2, 3, 5, 6, 9, 12가 된다.\"},{\"step 5\":\"중복을 제거한 숫자의 개수를 센다. 총 7개의 숫자가 있다.\"},{\"answer\":\"7\"}]','2025-09-29 05:22:55.923862','uploads/dab26e92-5639-42a3-a240-2f7e3e9e618a.png',NULL,1,NULL,12),(273,'[{\"step 1\":\"1부터 12까지의 숫자 중에서 3의 배수를 찾는다. 3, 6, 9, 12가 있다.\"},{\"step 2\":\"1부터 12까지의 숫자 중에서 10의 약수를 찾는다. 1, 2, 5, 10이 있다.\"},{\"step 3\":\"3의 배수이거나 10의 약수인 숫자를 모두 모은다. 1, 2, 3, 5, 6, 9, 10, 12가 있다.\"},{\"step 4\":\"중복을 제거한 후, 총 몇 개의 숫자가 있는지 센다. 총 8개의 숫자가 있다.\"},{\"answer\":\"8\"}]','2025-09-29 05:23:06.372899','uploads/dab26e92-5639-42a3-a240-2f7e3e9e618a.png',NULL,1,NULL,12),(274,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"3의 배수이거나 10의 약수인 숫자를 모두 합치면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"중복된 숫자를 제거하고 나면 총 8개의 숫자가 있다.\"},{\"answer\":\"8\"}]','2025-09-29 05:23:18.881360','uploads/dab26e92-5639-42a3-a240-2f7e3e9e618a.png',NULL,1,NULL,12),(275,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합치면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:24:30.797855','uploads/0f78fb2d-44ca-4af6-8668-5dfa3f8008c5.png',NULL,1,NULL,12),(276,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 상자 안의 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:24:38.770219','uploads/0f78fb2d-44ca-4af6-8668-5dfa3f8008c5.png',NULL,1,NULL,12),(277,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:25:18.002648','uploads/0f78fb2d-44ca-4af6-8668-5dfa3f8008c5.png',NULL,1,NULL,12),(278,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:25:41.938776','uploads/1bb99fca-ed2f-4d00-b645-b010a9eac4d3.png',NULL,1,NULL,12),(279,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:26:07.012689','uploads/1bb99fca-ed2f-4d00-b645-b010a9eac4d3.png',NULL,1,NULL,12),(280,'[{\"step 1\":\"주어진 정보를 이해한다. 선분 AB의 전체 길이는 8cm이고, 점 M은 이 선분의 중점이다.\"},{\"step 2\":\"중점의 정의를 상기한다. 중점은 선분을 두 개의 같은 길이의 선분으로 나눈다. 따라서 AM과 MB의 길이는 AB의 절반이다.\"},{\"step 3\":\"AM과 MB의 길이를 계산한다. |AB| = 8cm이므로, |AM| = |MB| = 8cm / 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 05:26:48.715368','uploads/f5326f83-85a6-452f-b2eb-ceb1c4414c0e.png',NULL,15,NULL,12),(281,'[{\"step 1\":\"문제에서 주어진 정보를 확인한다. 선분 AB의 길이는 8cm이고, M은 선분 AB의 중점이다.\"},{\"step 2\":\"중점의 정의에 따라, M은 선분 AB를 두 개의 같은 길이로 나눈다. 따라서 |AM| = |MB|이다.\"},{\"step 3\":\"선분 AB의 길이가 8cm이므로, |AM| = |MB| = 8cm / 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 05:27:23.732081','uploads/f5326f83-85a6-452f-b2eb-ceb1c4414c0e.png',NULL,15,NULL,12),(282,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"3의 배수이거나 10의 약수인 숫자를 모두 합치면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"이 숫자들의 개수를 세어보면 총 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:28:51.724340','uploads/92b8e607-1d5c-48fc-a12e-26ccbca6dfa7.png',NULL,1,NULL,12),(283,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"3의 배수이거나 10의 약수인 숫자를 모두 합치면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:32:43.445060','uploads/d36c98d3-08cd-4f8c-97d2-ca7ab349a56a.png',NULL,1,NULL,12),(284,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 중점 M에 의해 |AM|과 |MB|는 각각 AB의 절반이다.\"},{\"step 3\":\"따라서 |AM| = |MB| = 8cm ÷ 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 05:33:13.287198','uploads/f93490ff-715b-4ab6-ad51-1fb37c5bcf01.png',NULL,15,NULL,12),(285,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 상자 안의 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:36:25.881596','uploads/4ca9ee5f-9b5e-482d-a719-067207bf0f36.png',NULL,1,NULL,12),(286,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:36:43.304314','uploads/4ca9ee5f-9b5e-482d-a719-067207bf0f36.png',NULL,1,NULL,12),(287,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변환할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2는 (5x)^2로 표현할 수 있고, 1은 1^2로 표현할 수 있다. 따라서 중간항 -10x가 2ab 형태인지 확인한다.\"},{\"step 3\":\"중간항 -10x는 -2 * 5x * 1로 표현할 수 있다. 따라서 이 다항식은 (5x - 1)^2의 완전제곱식이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 05:38:07.638003','uploads/b732f744-15d9-4794-9c54-c5dc9b337123.png',NULL,8,NULL,12),(288,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수는 3, 6, 9, 12이고, 10의 약수는 1, 2, 5, 10이다.\"},{\"step 3\":\"두 조건을 만족하는 숫자를 모두 모으면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 4\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:38:27.786253','uploads/d8e2c51c-4153-4555-9d25-f1ba12d925a2.png',NULL,1,NULL,12),(289,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 중점 M에 의해 |AM|과 |MB|는 각각 AB의 절반이다.\"},{\"step 3\":\"따라서 |AM| = |MB| = 8cm ÷ 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 05:40:19.566550','uploads/238e501c-639e-4f01-afa6-fb290daf041c.png',NULL,15,NULL,12),(290,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 중점 M에 의해 |AM|과 |MB|는 각각 AB의 절반이다.\"},{\"step 3\":\"따라서 |AM| = |MB| = 8cm ÷ 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 05:40:28.422327','uploads/238e501c-639e-4f01-afa6-fb290daf041c.png',NULL,15,NULL,12),(291,'[{\"step 1\":\"1부터 12까지의 숫자 중에서 3의 배수를 찾는다. 3, 6, 9, 12가 있다.\"},{\"step 2\":\"1부터 12까지의 숫자 중에서 10의 약수를 찾는다. 1, 2, 5, 10이 있다.\"},{\"step 3\":\"3의 배수이거나 10의 약수인 숫자를 모두 모은다. 1, 2, 3, 5, 6, 9, 10, 12가 있다.\"},{\"step 4\":\"중복을 제거한 후, 총 몇 개의 숫자가 있는지 센다. 총 8개의 숫자가 있다.\"},{\"answer\":\"8\"}]','2025-09-29 05:41:26.789307','uploads/e4d7fd16-c7f7-4e8e-b020-611f6158c8ce.png',NULL,1,NULL,12),(292,'[{\"step 1\":\"1부터 12까지의 숫자 중에서 3의 배수를 찾는다. 3, 6, 9, 12가 있다.\"},{\"step 2\":\"1부터 12까지의 숫자 중에서 10의 약수를 찾는다. 1, 2, 5, 10이 있다.\"},{\"step 3\":\"두 조건 중 하나라도 만족하는 숫자를 찾는다. 3, 6, 9, 12, 1, 2, 5, 10이 있다.\"},{\"step 4\":\"중복된 숫자를 제거하고 고유한 숫자의 개수를 센다. 1, 2, 3, 5, 6, 9, 10, 12로 총 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:41:36.424353','uploads/e4d7fd16-c7f7-4e8e-b020-611f6158c8ce.png',NULL,1,NULL,12),(293,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:41:48.049170','uploads/e4d7fd16-c7f7-4e8e-b020-611f6158c8ce.png',NULL,1,NULL,12),(294,'[{\"step 1\":\"1부터 12까지의 숫자 중에서 3의 배수를 찾는다. 3, 6, 9, 12가 있다.\"},{\"step 2\":\"1부터 12까지의 숫자 중에서 10의 약수를 찾는다. 1, 2, 5, 10이 있다.\"},{\"step 3\":\"두 조건 중 하나라도 만족하는 숫자를 찾는다. 3, 6, 9, 12, 1, 2, 5, 10이 있다.\"},{\"step 4\":\"중복된 숫자를 제거하고 고유한 숫자를 센다. 1, 2, 3, 5, 6, 9, 10, 12로 총 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:46:23.723842','uploads/ea9aaec1-175b-4ab0-ab5d-0275e7e3169b.png',NULL,1,NULL,12),(295,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 중점 M에 의해 |AM|과 |MB|는 각각 AB의 절반이다.\"},{\"step 3\":\"따라서 |AM| = |MB| = 8cm ÷ 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 05:46:55.544631','uploads/eba9073a-25af-41e9-962b-6d213f491491.png',NULL,15,NULL,12),(296,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:47:44.832501','uploads/4717debd-8d93-4375-b64a-a4be2f0fe2c5.png',NULL,1,NULL,12),(297,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 중점 M에 의해 |AM|과 |MB|는 각각 AB의 절반이다.\"},{\"step 3\":\"따라서 |AM| = |MB| = 8cm ÷ 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 05:51:18.550214','uploads/e1b72458-2bbb-42eb-b48d-02069b65cff2.png',NULL,15,NULL,12),(298,'[{\"step 1\":\"1부터 12까지의 숫자 중 3의 배수를 찾는다. 3, 6, 9, 12가 있다.\"},{\"step 2\":\"1부터 12까지의 숫자 중 10의 약수를 찾는다. 1, 2, 5, 10이 있다.\"},{\"step 3\":\"두 집합을 합치고 중복을 제거한다. 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 4\":\"중복을 제거한 집합의 원소 개수를 센다. 총 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 05:51:48.499204','uploads/6252f7cb-9920-46c2-983c-f0ecbed9ac65.png',NULL,1,NULL,12),(299,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 중점 M에 의해 |AM|과 |MB|는 각각 AB의 절반이다.\"},{\"step 3\":\"따라서 |AM| = |MB| = 8cm ÷ 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 05:52:37.228911','uploads/f66b58b7-4446-401b-aa68-7fcbdd1b8b72.png',NULL,15,NULL,12),(300,'[{\"step 1\":\"문제에서 주어진 정보를 확인한다. |AB| = 8cm이고, M은 AB의 중점이다.\"},{\"step 2\":\"중점의 정의에 따라, |AM| = |MB|가 성립한다. 따라서 |AB| = |AM| + |MB| = 2|AM|이다.\"},{\"step 3\":\"주어진 |AB| = 8cm를 이용하여 식을 세운다: 8cm = 2|AM|.\"},{\"step 4\":\"양변을 2로 나누어 |AM|의 값을 구한다: |AM| = 8cm / 2 = 4cm.\"},{\"answer\":\"|AM| = 4cm\"}]','2025-09-29 05:55:36.436595','uploads/f453e2fa-8f7d-47ef-bb9d-01631c82a7a8.png',NULL,15,NULL,12),(301,'[{\"step 1\":\"주어진 정보를 확인한다. 선분 AB의 전체 길이는 8cm이고, 점 M은 선분 AB의 중점이다.\"},{\"step 2\":\"중점의 성질을 이해한다. 중점은 선분을 두 개의 같은 길이로 나눈다. 따라서 M이 AB의 중점이라면, AM의 길이는 MB의 길이와 같다.\"},{\"step 3\":\"중점의 성질을 이용하여 길이를 계산한다. M이 AB를 반으로 나누므로, AM = (AB의 길이) / 2이다. 주어진 값을 대입하면, AM = 8cm / 2 = 4cm이다.\"},{\"step 4\":\"결론을 내린다. 점 A에서 중점 M까지의 길이는 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 05:56:17.446267','uploads/f453e2fa-8f7d-47ef-bb9d-01631c82a7a8.png',NULL,15,NULL,12),(302,'[{\"step 1\":\"1부터 12까지의 숫자 중에서 3의 배수를 찾는다. 3, 6, 9, 12가 3의 배수이다.\"},{\"step 2\":\"1부터 12까지의 숫자 중에서 10의 약수를 찾는다. 1, 2, 5, 10이 10의 약수이다.\"},{\"step 3\":\"3의 배수이거나 10의 약수인 숫자를 모두 모은다. 중복을 제거하면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 4\":\"모은 숫자의 개수를 센다. 총 8개의 숫자가 있다.\"},{\"answer\":\"8\"}]','2025-09-29 05:56:31.312601','uploads/eae01a08-d374-48cb-b6fc-104b1a2b2673.png',NULL,1,NULL,12),(303,'[{\"step 1\":\"문제에서 주어진 정보를 이해한다. 선분 AB의 전체 길이는 8cm이고, 점 M은 선분 AB의 중점이다.\"},{\"step 2\":\"중점의 성질을 상기한다. 중점은 선분을 두 개의 같은 길이로 나눈다. 따라서 |AM| = |MB|이다.\"},{\"step 3\":\"선분 AB의 길이를 반으로 나누어 |AM|의 길이를 계산한다. |AM| = |AB| / 2 = 8cm / 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 06:01:37.465508','uploads/9e58142f-1c45-422a-8082-c06b4357a5b0.png',NULL,15,NULL,12),(304,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 중점 M에 의해 |AM|과 |MB|는 각각 AB의 절반이다.\"},{\"step 3\":\"따라서 |AM| = |MB| = 8cm ÷ 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 06:01:51.809487','uploads/9e58142f-1c45-422a-8082-c06b4357a5b0.png',NULL,15,NULL,12),(305,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 중점 M에 의해 |AM|과 |MB|는 각각 AB의 절반이다.\"},{\"step 3\":\"따라서 |AM| = |MB| = 8cm ÷ 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 06:02:01.690887','uploads/9e58142f-1c45-422a-8082-c06b4357a5b0.png',NULL,15,NULL,12),(306,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"3의 배수이거나 10의 약수인 숫자를 모두 모으면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 06:07:38.979969','uploads/f25ce752-1bdd-4dd7-8b57-4d41c1c9ae6a.png',NULL,1,NULL,12),(307,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x)^2 - 2*5x*1 + 1^2의 형태로, 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 06:08:09.389566','uploads/724000c9-2183-4d29-8b83-5b45e7d813dc.png',NULL,8,NULL,12),(308,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x - 1)(5x - 1)로 인수분해된다.\"},{\"step 3\":\"따라서, 주어진 다항식의 인수분해 결과는 (5x - 1)^2이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 06:08:21.773545','uploads/724000c9-2183-4d29-8b83-5b45e7d813dc.png',NULL,8,NULL,12),(309,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x - 1)(5x - 1)로 인수분해된다.\"},{\"step 3\":\"따라서, 주어진 다항식의 인수분해 결과는 (5x - 1)^2이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 06:10:39.160685','uploads/8e66ca7a-0048-457d-8f1b-b9868acd9227.png',NULL,8,NULL,12),(310,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x - 1)(5x - 1)로 인수분해된다.\"},{\"step 3\":\"따라서, 주어진 다항식의 인수분해 결과는 (5x - 1)^2이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 06:10:49.673341','uploads/8e66ca7a-0048-457d-8f1b-b9868acd9227.png',NULL,8,NULL,12),(311,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 06:12:36.849014','uploads/ff187a9b-8591-491b-8b7a-d88d3dcf6403.png',NULL,1,NULL,12),(312,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 06:12:46.493282','uploads/ff187a9b-8591-491b-8b7a-d88d3dcf6403.png',NULL,1,NULL,12),(313,'[{\"step 1\":\"문제 이해: 선분 AB가 주어져 있으며, M은 그 중점이다. |AB|의 길이는 8cm이다. |AM|의 길이를 구해야 한다.\"},{\"step 2\":\"중점의 성질: 중점은 선분을 두 개의 같은 길이로 나눈다. 따라서 |AM| = |MB|이다.\"},{\"step 3\":\"길이 계산: |AB| = |AM| + |MB|이고, |AM| = |MB|이므로, 2|AM| = 8cm이다.\"},{\"step 4\":\"방정식 풀기: 2|AM| = 8cm에서 양변을 2로 나누면 |AM| = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 06:14:05.519049','uploads/eeef8d26-2213-4751-8e6e-73b08b9c31b5.png',NULL,15,NULL,12),(314,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 즉, |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 따라서 |AM| + |MB| = 8cm이다.\"},{\"step 3\":\"점 M이 중점이므로 |AM| = |MB| = 8cm / 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 06:14:14.612622','uploads/eeef8d26-2213-4751-8e6e-73b08b9c31b5.png',NULL,15,NULL,12),(315,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변환할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변환할 수 있다. 이는 (5x - 1)(5x - 1)로 인수분해된다.\"},{\"step 3\":\"따라서, 주어진 다항식의 인수분해 결과는 (5x - 1)^2이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 06:16:32.161122','uploads/34aa0e34-96f4-45b3-ac93-b2c51c5f3efb.png',NULL,8,NULL,12),(316,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x - 1)(5x - 1)로 인수분해된다.\"},{\"step 3\":\"따라서, 주어진 다항식의 인수분해 결과는 (5x - 1)^2이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 06:16:50.871974','uploads/34aa0e34-96f4-45b3-ac93-b2c51c5f3efb.png',NULL,8,NULL,12),(317,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 상자 안의 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 06:18:53.406574','uploads/c254073c-6928-493c-9fcc-8fd9fc734b18.png',NULL,1,NULL,12),(318,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 06:19:19.066836','uploads/c254073c-6928-493c-9fcc-8fd9fc734b18.png',NULL,1,NULL,12),(319,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 06:22:01.444469','uploads/4851bb97-7d09-49ec-9264-24b976f15830.png',NULL,1,NULL,12),(320,'[{\"step 1\":\"문제에서 1부터 12까지의 숫자가 적힌 공이 각각 하나씩 들어 있는 상자가 있다. 이 중에서 숫자가 3의 배수이거나 10의 약수인 공의 개수를 구해야 한다.\"},{\"step 2\":\"3의 배수인 숫자를 찾는다. 1부터 12까지의 숫자 중 3의 배수는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자를 찾는다. 1부터 12까지의 숫자 중 10의 약수는 1, 2, 5, 10이다.\"},{\"step 4\":\"3의 배수이거나 10의 약수인 숫자를 모두 합친다. 중복된 숫자를 제거하면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 5\":\"중복을 제거한 숫자의 개수를 센다. 총 8개의 숫자가 있다.\"},{\"answer\":\"8\"}]','2025-09-29 06:23:16.979433','uploads/2ce05c8e-4a17-40b7-87f2-33f7a417cb49.png',NULL,1,NULL,12),(321,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 06:23:35.241964','uploads/2ce05c8e-4a17-40b7-87f2-33f7a417cb49.png',NULL,1,NULL,12),(322,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 06:25:40.684572','uploads/d37fd6ff-e3c2-46ee-ae74-856edbde2fde.png',NULL,1,NULL,12),(323,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 06:25:58.187484','uploads/d37fd6ff-e3c2-46ee-ae74-856edbde2fde.png',NULL,1,NULL,12),(324,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수는 3, 6, 9, 12이고, 10의 약수는 1, 2, 5, 10이다.\"},{\"step 3\":\"두 조건을 만족하는 숫자를 모두 모으면 1, 2, 3, 5, 6, 9, 10, 12가 된다.\"},{\"step 4\":\"따라서 상자 안의 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 06:28:08.519285','uploads/d37fd6ff-e3c2-46ee-ae74-856edbde2fde.png',NULL,1,NULL,12),(325,'[{\"step 1\":\"문제에서 주어진 조건에 따라 1부터 12까지의 숫자 중 3의 배수이거나 10의 약수인 숫자를 찾는다.\"},{\"step 2\":\"3의 배수인 숫자는 3, 6, 9, 12이다.\"},{\"step 3\":\"10의 약수인 숫자는 1, 2, 5, 10이다.\"},{\"step 4\":\"두 조건을 모두 만족하는 숫자를 합집합으로 구하면 1, 2, 3, 5, 6, 9, 10, 12이다.\"},{\"step 5\":\"따라서 조건을 만족하는 공의 개수는 8개이다.\"},{\"answer\":\"8\"}]','2025-09-29 06:31:34.548056','uploads/5cf8f148-5e07-4c4d-8efe-2822a6494813.png',NULL,1,NULL,12),(326,'[{\"step 1\":\"문제를 이해하자. 1부터 12까지의 숫자가 적힌 공이 각각 하나씩 들어 있는 상자가 있다. 이 중에서 숫자가 3의 배수이거나 15의 약수인 공의 개수를 찾아야 한다.\"},{\"step 2\":\"3의 배수를 찾자. 1부터 12까지의 숫자 중 3의 배수는 3, 6, 9, 12이다.\"},{\"step 3\":\"15의 약수를 찾자. 15의 약수는 1, 3, 5, 15이다. 하지만 1부터 12까지의 범위 내에서만 고려하므로 1, 3, 5가 해당된다.\"},{\"step 4\":\"두 조건 중 하나라도 만족하는 숫자를 찾자. 3의 배수는 3, 6, 9, 12이고, 15의 약수는 1, 3, 5이다. 이들을 합치면 1, 3, 5, 6, 9, 12가 된다.\"},{\"step 5\":\"중복을 제거하고 최종적으로 조건을 만족하는 숫자의 개수를 세자. 1, 3, 5, 6, 9, 12로 총 6개이다.\"},{\"answer\":\"6\"}]','2025-09-29 06:33:51.048448','uploads/5cf8f148-5e07-4c4d-8efe-2822a6494813.png',NULL,1,NULL,12),(327,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 중점 M에 의해 |AM|과 |MB|는 각각 AB의 절반이다.\"},{\"step 3\":\"따라서 |AM| = |MB| = 8cm ÷ 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 06:34:00.141837','uploads/af018314-9a90-44b0-b617-6a3c5597e6bf.png',NULL,15,NULL,12),(328,'[{\"step 1\":\"문제에서 주어진 정보를 확인한다. 선분 AB의 길이는 8cm이고, M은 AB의 중점이다.\"},{\"step 2\":\"중점의 정의에 따라, M은 선분 AB를 두 개의 같은 길이로 나눈다. 즉, |AM| = |MB|이다.\"},{\"step 3\":\"선분 AB의 전체 길이가 8cm이므로, |AM| + |MB| = 8cm이다. |AM| = |MB|이므로, 2|AM| = 8cm이다.\"},{\"step 4\":\"2|AM| = 8cm를 풀어 |AM|의 값을 구한다. |AM| = 8cm / 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 06:34:55.196546','uploads/af018314-9a90-44b0-b617-6a3c5597e6bf.png',NULL,15,NULL,12),(329,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 즉, |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 따라서 |AM| + |MB| = 8cm이다.\"},{\"step 3\":\"점 M이 중점이므로 |AM| = |MB| = 8cm / 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 06:35:07.616493','uploads/af018314-9a90-44b0-b617-6a3c5597e6bf.png',NULL,15,NULL,12),(330,'[{\"step 1\":\"문제에서 주어진 정보를 이해한다. 점 M은 선분 AB의 중점이며, |AB| = 8cm이다. 중점은 선분을 두 개의 같은 길이로 나눈다.\"},{\"step 2\":\"중점의 정의에 따라 |AM| = |MB|가 성립한다. 따라서 |AM|은 |AB|의 절반이다.\"},{\"step 3\":\"|AB| = 8cm이므로, |AM| = |AB| / 2 = 8cm / 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 06:35:27.970878','uploads/af018314-9a90-44b0-b617-6a3c5597e6bf.png',NULL,15,NULL,12),(331,'[{\"step 1\":\"문제에서 주어진 정보를 확인한다. 선분 AB의 길이는 8cm이고, M은 AB의 중점이다.\"},{\"step 2\":\"중점의 정의에 따라, M은 선분 AB를 두 개의 같은 길이로 나눈다. 따라서 |AM| = |MB|이다.\"},{\"step 3\":\"선분 AB의 전체 길이가 8cm이므로, |AM| = |MB| = 8cm / 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 06:36:21.174217','uploads/af018314-9a90-44b0-b617-6a3c5597e6bf.png',NULL,15,NULL,12),(332,'[{\"step 1\":\"문제에서 x와 y가 정비례한다고 했으므로, y = kx의 형태로 나타낼 수 있다. 여기서 k는 비례상수이다.\"},{\"step 2\":\"x=3일 때 y=5이므로, 5 = k * 3을 통해 k를 구할 수 있다. 따라서 k = 5/3이다.\"},{\"step 3\":\"이제 x=9일 때 y의 값을 구하기 위해 y = (5/3) * 9를 계산한다.\"},{\"step 4\":\"계산하면 y = 15가 된다.\"},{\"answer\":\"15\"}]','2025-09-29 06:41:26.739120','uploads/5c6a7f70-fadd-4dc9-b9e1-5729cf1c0d73.png',NULL,9,NULL,12),(333,'[{\"step 1\":\"문제에서 x와 y가 정비례한다고 했으므로, y = kx의 형태로 나타낼 수 있다. 여기서 k는 비례상수이다.\"},{\"step 2\":\"x=3일 때 y=5이므로, 5 = k * 3을 통해 k를 구할 수 있다. 따라서 k = 5/3이다.\"},{\"step 3\":\"이제 x=9일 때 y의 값을 구하기 위해 y = (5/3) * 9를 계산한다.\"},{\"step 4\":\"계산 결과 y = 15가 된다.\"},{\"answer\":\"15\"}]','2025-09-29 06:41:47.913133','uploads/5c6a7f70-fadd-4dc9-b9e1-5729cf1c0d73.png',NULL,9,NULL,12),(334,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 중간 지점이므로, 학교에서 P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 가는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 버스를 타고 P까지 가는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 4\":\"그룹 B는 P에서 내려서 걸어가고, 버스는 돌아와서 그룹 A를 태운다. 그룹 A가 P에 도착할 때까지 버스는 1.3시간 - 0.13시간 = 1.17시간 동안 이동할 수 있다.\"},{\"step 5\":\"버스는 1.17시간 동안 50km/h로 이동하므로, 1.17시간 * 50km/h = 58.5km를 이동할 수 있다. 하지만 실제로는 6.5km만 이동하고 돌아와야 하므로, 그룹 A를 태우고 남은 거리를 이동한다.\"},{\"step 6\":\"결국 그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"},{\"answer\":\"그룹 A와 그룹 B는 각각 6.5km를 걸었다.\"}]','2025-09-29 06:44:48.276456','uploads/307f05a1-9ebc-405e-bbb4-133d89134a13.png',NULL,9,NULL,12),(335,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 학교와 경기장 사이의 중간 지점이므로, P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 도달하는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 50km/h의 속도로 6.5km를 이동하므로, P까지 도달하는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 4\":\"그룹 B는 P에서 내려 걷기 시작하고, 버스는 즉시 돌아가 그룹 A를 태운다. 그룹 A는 버스를 타고 남은 6.5km를 이동한다.\"},{\"step 5\":\"그룹 A가 버스를 타고 남은 6.5km를 이동하는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다. 따라서 그룹 A와 그룹 B는 동시에 경기장에 도착한다.\"},{\"step 6\":\"그룹 A는 처음 6.5km를 걸었고, 그룹 B는 처음 6.5km를 버스를 타고 갔다. 따라서 그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"},{\"answer\":\"그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"}]','2025-09-29 06:45:07.107845','uploads/307f05a1-9ebc-405e-bbb4-133d89134a13.png',NULL,9,NULL,12),(336,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 학교와 경기장 사이의 중간 지점이므로, P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 도달하는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 50km/h의 속도로 6.5km를 이동하므로, P까지 도달하는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 4\":\"그룹 B는 P에서 내려 걷기 시작하고, 버스는 즉시 돌아가 그룹 A를 태운다. 그룹 A가 P에 도착할 때까지 버스는 1.3시간 - 0.13시간 = 1.17시간 동안 이동할 수 있다.\"},{\"step 5\":\"버스는 1.17시간 동안 50km/h의 속도로 이동하므로, 1.17시간 * 50km/h = 58.5km를 이동할 수 있다. 하지만 버스는 P에서 돌아가야 하므로, 실제로는 6.5km만 이동하고 다시 돌아온다.\"},{\"step 6\":\"그룹 A는 버스를 타고 나머지 6.5km를 이동하고, 그룹 B는 P에서 경기장까지 6.5km를 걷는다. 따라서 그룹 A는 6.5km를 걷고, 그룹 B는 6.5km를 걷는다.\"},{\"answer\":\"그룹 A는 6.5km를 걷고, 그룹 B는 6.5km를 걷는다.\"}]','2025-09-29 06:48:00.150898','uploads/16ea7871-8718-4ef9-9a8f-bf61c0bc98f9.png',NULL,9,NULL,12),(337,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 학교와 경기장 사이의 중간 지점이므로, P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 도달하는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 50km/h의 속도로 6.5km를 이동하므로, P까지 도달하는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 4\":\"그룹 B는 P에서 내려 걷기 시작하고, 버스는 즉시 돌아가 그룹 A를 태운다. 그룹 A는 버스를 타고 남은 6.5km를 이동한다.\"},{\"step 5\":\"그룹 A가 버스를 타고 남은 거리를 이동하는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다. 따라서 그룹 A와 그룹 B는 동시에 경기장에 도착한다.\"},{\"step 6\":\"그룹 A는 처음 6.5km를 걸었고, 그룹 B는 처음 6.5km를 버스로 이동한 후 나머지 6.5km를 걸었다.\"},{\"answer\":\"그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"}]','2025-09-29 06:48:44.993983','uploads/16ea7871-8718-4ef9-9a8f-bf61c0bc98f9.png',NULL,9,NULL,12),(338,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 학교와 경기장 사이의 중간 지점이므로, P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 도달하는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 50km/h의 속도로 6.5km를 이동하므로, P까지 도달하는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 4\":\"그룹 B는 P에서 내려 걷기 시작하고, 버스는 즉시 돌아가 그룹 A를 태운다. 그룹 A는 버스를 타고 남은 6.5km를 이동한다.\"},{\"step 5\":\"그룹 A가 버스를 타고 6.5km를 이동하는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다. 따라서 그룹 A와 그룹 B는 동시에 경기장에 도착한다.\"},{\"step 6\":\"그룹 A는 총 6.5km를 걸었고, 그룹 B는 P까지 6.5km를 버스로 이동한 후 나머지 6.5km를 걸었다.\"},{\"answer\":\"그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"}]','2025-09-29 06:49:10.663997','uploads/16ea7871-8718-4ef9-9a8f-bf61c0bc98f9.png',NULL,9,NULL,12),(339,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 중간 지점이므로, 학교에서 P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 도달하는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 50km/h의 속도로 6.5km를 이동하므로, P까지 도달하는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 4\":\"그룹 B는 P에서 내려서 걷기 시작하고, 버스는 즉시 돌아가서 그룹 A를 픽업한다. 그룹 A가 P에 도착할 때까지 버스는 1.3시간 - 0.13시간 = 1.17시간 동안 이동할 수 있다.\"},{\"step 5\":\"버스는 1.17시간 동안 50km/h의 속도로 이동하므로, 1.17시간 * 50km/h = 58.5km를 이동할 수 있다. 하지만 실제로는 6.5km만 이동하면 되므로, 버스는 충분히 그룹 A를 픽업하고 경기장까지 갈 수 있다.\"},{\"step 6\":\"결국, 그룹 A는 6.5km를 걷고, 그룹 B는 6.5km를 걷는다. 두 그룹 모두 경기장까지의 나머지 거리는 버스를 타고 이동한다.\"},{\"answer\":\"그룹 A는 6.5km를 걷고, 그룹 B는 6.5km를 걷는다.\"}]','2025-09-29 06:49:40.582518','uploads/16ea7871-8718-4ef9-9a8f-bf61c0bc98f9.png',NULL,9,NULL,12),(340,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x - 1)(5x - 1)로 인수분해된다.\"},{\"step 3\":\"따라서, 주어진 다항식 25x^2 - 10x + 1은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 14:32:11.785741','uploads/b738a62c-23f9-4a80-8df2-118fa9779030.png',NULL,8,NULL,12),(341,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변환할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변환할 수 있다. 이는 (5x - 1)(5x - 1)로 인수분해된다.\"},{\"step 3\":\"따라서, 주어진 다항식의 인수분해 결과는 (5x - 1)^2이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 14:32:34.837630','uploads/b738a62c-23f9-4a80-8df2-118fa9779030.png',NULL,8,NULL,12),(342,'[{\"step 1\":\"문제에 따르면, 점 M은 선분 AB의 중점이다. 따라서 |AM| = |MB|이다.\"},{\"step 2\":\"선분 AB의 전체 길이는 8cm이다. 중점 M에서 선분 AB를 두 개의 같은 길이로 나누므로, |AM| = |MB| = 8cm / 2이다.\"},{\"step 3\":\"계산을 통해 |AM| = 4cm임을 알 수 있다.\"},{\"answer\":\"4cm\"}]','2025-09-29 14:33:10.335080','uploads/6f44a104-5b80-47b9-8664-c5e18abe7139.png',NULL,15,NULL,12),(343,'[{\"step 1\":\"문제에서 주어진 정보를 확인한다. 선분 AB의 길이는 8cm이고, M은 선분 AB의 중점이다.\"},{\"step 2\":\"중점의 정의에 따라, M은 A와 B 사이의 중간 지점이다. 따라서 |AM| = |MB|이다.\"},{\"step 3\":\"선분 AB의 전체 길이가 8cm이므로, |AM| + |MB| = 8cm이다. |AM| = |MB|이므로, 2|AM| = 8cm이다.\"},{\"step 4\":\"양변을 2로 나누어 |AM|의 길이를 구한다. |AM| = 8cm / 2 = 4cm이다.\"},{\"answer\":\"4cm\"}]','2025-09-29 14:33:23.295993','uploads/6f44a104-5b80-47b9-8664-c5e18abe7139.png',NULL,15,NULL,12),(344,'[{\"step 1\":\"1부터 12까지의 숫자 중에서 3의 배수를 찾는다. 3, 6, 9, 12가 있다.\"},{\"step 2\":\"1부터 12까지의 숫자 중에서 10의 약수를 찾는다. 1, 2, 5, 10이 있다.\"},{\"step 3\":\"3의 배수이거나 10의 약수인 숫자를 모두 모은다. 1, 2, 3, 5, 6, 9, 10, 12가 있다.\"},{\"step 4\":\"중복을 제거한 후, 총 몇 개의 숫자가 있는지 센다. 총 8개의 숫자가 있다.\"},{\"answer\":\"8\"}]','2025-09-29 14:34:53.173550','uploads/66264f30-291d-4cd0-ba07-76b81c3e4e91.png',NULL,1,NULL,12),(345,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2는 (5x)^2로 표현할 수 있고, 1은 1^2로 표현할 수 있다. 따라서 중간 항 -10x가 2ab 형태인지 확인한다.\"},{\"step 3\":\"중간 항 -10x는 -2 * 5x * 1로 표현할 수 있다. 따라서 이 다항식은 (5x - 1)^2의 완전제곱식이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 14:42:35.055989','uploads/e0dac3c8-4914-498f-bf2d-7e0ec7845050.png',NULL,8,NULL,12),(346,'[{\"step 1\":\"문제에서 x와 y가 정비례한다고 했으므로, y = kx의 형태로 나타낼 수 있다. 여기서 k는 비례상수이다.\"},{\"step 2\":\"x=3일 때 y=5이므로, 5 = k * 3을 통해 k를 구할 수 있다. 따라서 k = 5/3이다.\"},{\"step 3\":\"이제 x=9일 때 y의 값을 구하기 위해 y = (5/3) * 9를 계산한다.\"},{\"step 4\":\"계산하면 y = 15가 된다.\"},{\"answer\":\"15\"}]','2025-09-29 14:47:10.522967','uploads/aece7ecf-fae2-4344-83b1-1eb517a13845.png',NULL,9,NULL,12),(347,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 중간 지점이므로, 학교에서 P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 도달하는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 50km/h의 속도로 6.5km를 이동하므로, P까지 도달하는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 4\":\"그룹 B는 P에서 내려서 걷기 시작하고, 버스는 즉시 돌아가서 그룹 A를 태운다. 그룹 A가 P에 도착할 때까지 버스는 1.3시간 - 0.13시간 = 1.17시간 동안 이동할 수 있다.\"},{\"step 5\":\"버스는 1.17시간 동안 50km/h로 이동하므로, 1.17시간 * 50km/h = 58.5km를 이동할 수 있다. 하지만 실제로는 6.5km만 이동하면 되므로, 버스는 그룹 A를 태우고 경기장까지 이동한다.\"},{\"step 6\":\"그룹 A는 P까지 6.5km를 걸었고, 그룹 B는 P에서 경기장까지 6.5km를 걸었다. 따라서 두 그룹 모두 6.5km를 걸었다.\"},{\"answer\":\"각 그룹은 6.5km를 걸었다.\"}]','2025-09-29 14:57:58.741228','uploads/f540a2c5-f728-4bf4-9344-9e8fa71e74ff.png',NULL,9,NULL,12),(348,'[{\"step 1\":\"문제에서 주어진 정보를 정리합니다. 학교에서 경기장까지의 거리는 13km입니다. 그룹 A는 시속 5km로 걷고, 그룹 B는 시속 50km로 버스를 탑니다. 그룹 B는 중간 지점인 P에서 버스에서 내려 걷기 시작하고, 버스는 즉시 돌아가 그룹 A를 태우고 경기장으로 갑니다. 두 그룹은 동시에 경기장에 도착합니다.\"},{\"step 2\":\"중간 지점 P까지의 거리를 계산합니다. P는 학교와 경기장 사이의 중간 지점이므로, P까지의 거리는 13km의 절반인 6.5km입니다.\"},{\"step 3\":\"그룹 B가 버스를 타고 P까지 도달하는 데 걸리는 시간을 계산합니다. 그룹 B의 버스 속도는 시속 50km이므로, P까지 도달하는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간입니다.\"},{\"step 4\":\"그룹 A가 P까지 걷는 데 걸리는 시간을 계산합니다. 그룹 A의 걷는 속도는 시속 5km이므로, P까지 걷는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간입니다.\"},{\"step 5\":\"버스가 그룹 A를 태우고 경기장까지 가는 시간을 계산합니다. 버스는 P에서 그룹 A를 태우고 남은 6.5km를 시속 50km로 이동하므로, 걸리는 시간은 6.5km / 50km/h = 0.13시간입니다.\"},{\"step 6\":\"두 그룹이 동시에 도착하기 위해 그룹 A가 버스를 타고 이동한 거리와 걷는 거리를 고려하여 최종적으로 각 그룹이 걷는 거리를 계산합니다. 그룹 A는 총 6.5km를 걷고, 그룹 B는 P 이후 6.5km를 걷습니다.\"},{\"answer\":\"그룹 A와 그룹 B는 각각 6.5km를 걸었습니다.\"}]','2025-09-29 14:59:59.216337','uploads/284fae9d-2b9e-451a-b009-fbb1d8449ecc.png',NULL,9,NULL,12),(349,'[{\"step 1\":\"문제를 이해한다. 두 그룹 A와 B가 학교에서 출발하여 13km 떨어진 경기장으로 간다. 그룹 A는 시속 5km로 걷고, 그룹 B는 시속 50km로 버스를 타고 간다. 중간 지점 P에서 그룹 B는 버스에서 내려 걷기 시작하고, 버스는 그룹 A를 태우러 돌아간다. 두 그룹은 동시에 경기장에 도착한다. 각 그룹이 걸은 거리를 구하라.\"},{\"step 2\":\"주어진 정보를 정리한다. 학교에서 경기장까지의 총 거리는 13km이다. 중간 지점 P는 학교에서 6.5km 떨어져 있다. 그룹 A의 걷는 속도는 5km/h이고, 그룹 B가 타는 버스의 속도는 50km/h이다.\"},{\"step 3\":\"그룹 B의 여정을 분석한다. 그룹 B는 버스를 타고 6.5km 떨어진 지점 P까지 간 후, 버스에서 내려 걷기 시작한다. 버스는 즉시 돌아가서 그룹 A를 태우고 경기장으로 간다. 그룹 B는 P에서 경기장까지 걷는다.\"},{\"step 4\":\"그룹 A의 여정을 분석한다. 그룹 A는 처음부터 끝까지 걷는다. 버스가 그룹 A를 태우러 돌아오는 동안 그룹 A는 계속 걷고 있다. 그룹 A가 걸은 거리와 그룹 B가 걸은 거리의 합이 13km가 되어야 한다.\"},{\"step 5\":\"두 그룹이 동시에 도착하므로, 그룹 A가 걸은 시간과 그룹 B가 걸은 시간은 같다. 그룹 A가 걸은 거리를 x라 하면, 그룹 B가 걸은 거리는 13 - x이다. 그룹 A의 걷는 시간은 x/5이고, 그룹 B의 걷는 시간은 (13-x)/50이다. 두 시간이 같으므로, x/5 = (13-x)/50을 풀어 x를 구한다.\"},{\"step 6\":\"x/5 = (13-x)/50을 풀면, 50x = 5(13-x)이다. 이를 풀면 50x = 65 - 5x이고, 55x = 65가 된다. 따라서 x = 65/55 = 1.18km이다. 그룹 A는 1.18km를 걸었고, 그룹 B는 13 - 1.18 = 11.82km를 걸었다.\"},{\"answer\":\"그룹 A는 1.18km를 걸었고, 그룹 B는 11.82km를 걸었다.\"}]','2025-09-29 15:05:14.647689','uploads/18eabe3d-5c3d-4b12-9208-143568745894.png',NULL,9,NULL,12),(350,'[{\"step 1\":\"문제를 이해한다. 두 그룹 A와 B가 동시에 출발하여 13km 떨어진 경기장으로 이동한다. 그룹 A는 시속 5km로 걷고, 그룹 B는 시속 50km로 버스를 타고 중간 지점 P에서 내려 걷는다. 버스는 즉시 돌아가서 그룹 A를 태우고 경기장으로 간다. 두 그룹은 동시에 도착한다.\"},{\"step 2\":\"그룹 A의 이동 시간을 계산한다. 그룹 A는 13km를 시속 5km로 걷는다. 따라서 이동 시간은 13/5 시간이다.\"},{\"step 3\":\"그룹 B의 이동을 분석한다. 그룹 B는 처음 6.5km를 버스로 이동하고 나머지 6.5km를 걷는다. 버스는 그룹 A를 태우러 돌아가고 다시 경기장으로 간다.\"},{\"step 4\":\"그룹 B의 총 이동 시간을 계산한다. 버스 이동 시간은 6.5/50 시간, 걷는 시간은 6.5/5 시간이다. 그룹 A를 태우러 가는 시간과 돌아오는 시간도 고려해야 한다.\"},{\"step 5\":\"두 그룹의 총 이동 시간이 같아야 하므로, 그룹 A의 이동 시간과 그룹 B의 총 이동 시간을 같게 설정하여 방정식을 푼다.\"},{\"step 6\":\"계산을 통해 각 그룹이 걸은 거리를 구한다. 그룹 A는 13km를 걸었고, 그룹 B는 6.5km를 걸었다.\"},{\"answer\":\"그룹 A는 13km를 걸었고, 그룹 B는 6.5km를 걸었다.\"}]','2025-09-29 15:13:12.267718','uploads/21d52ff2-85c6-4911-bccb-b0aa22e017e7.png',NULL,9,NULL,12),(351,'[{\"step 1\":\"주어진 식을 확인한다: <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>.\"},{\"step 2\":\"모든 항이 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>를 포함하므로, 계수를 합칠 수 있다.\"},{\"step 3\":\"먼저 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>를 계산한다. 이는 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>이므로 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>가 된다.\"},{\"step 4\":\"이제 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>를 계산한다. 이는 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>이므로 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>가 된다.\"},{\"answer\":\"2\\\\sqrt{2}\"}]','2025-09-29 15:13:55.722818','uploads/e00ff8a5-7770-4ce5-9d0b-76c8c1fd269c.png',NULL,5,NULL,12),(352,'[{\"step 1\":\"문제에서 x와 y가 정비례한다고 주어졌습니다. 이는 x와 y의 비율이 일정하다는 것을 의미합니다.\"},{\"step 2\":\"주어진 조건에 따라 x=3일 때 y=5입니다. 따라서 비례 상수 k는 y/x = 5/3입니다.\"},{\"step 3\":\"x가 9일 때 y의 값을 구하기 위해 비례식을 사용합니다. y = kx = (5/3) * 9입니다.\"},{\"step 4\":\"계산을 통해 y = 15가 됩니다.\"},{\"answer\":\"y = 15\"}]','2025-09-29 15:20:33.759965','uploads/e6cdae46-6a20-476a-8e0f-450df943c4e7.png',NULL,9,NULL,12),(353,'[{\"step 1\":\"문제에서 그룹 A와 B가 동시에 출발하여 경기장에 도착하는 상황을 고려한다. 그룹 A는 5km/h로 걷고, 그룹 B는 50km/h로 버스를 타고 간다. P 지점은 학교와 경기장 사이의 중간 지점이다.\"},{\"step 2\":\"P 지점까지의 거리는 6.5km이다. 그룹 B는 버스를 타고 P 지점까지 6.5km를 이동한 후 걸어서 나머지 6.5km를 이동한다. 그룹 A는 처음부터 끝까지 걸어서 13km를 이동한다.\"},{\"step 3\":\"그룹 B가 P 지점까지 버스를 타고 이동하는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다. 나머지 6.5km를 걷는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다. 따라서 그룹 B의 총 이동 시간은 0.13 + 1.3 = 1.43시간이다.\"},{\"step 4\":\"그룹 A가 13km를 걷는 데 걸리는 시간은 13km / 5km/h = 2.6시간이다. 그룹 B가 버스를 타고 P 지점까지 이동한 후 걸어서 경기장까지 도착하는 시간과 그룹 A가 걸어서 경기장까지 도착하는 시간이 같아야 하므로, 버스는 그룹 A를 태우고 나머지 거리를 이동해야 한다.\"},{\"step 5\":\"버스가 그룹 A를 태우고 이동하는 거리는 13km - 6.5km = 6.5km이다. 버스가 이 거리를 이동하는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다. 따라서 그룹 A가 버스를 타고 이동한 거리는 6.5km이다.\"},{\"answer\":\"그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"}]','2025-09-29 15:22:18.861740','uploads/265cbe02-3243-420a-98ed-20526f95582a.png',NULL,9,NULL,12),(354,'[{\"step 1\":\"문제에서 x와 y가 정비례한다고 했으므로, y = kx의 형태로 나타낼 수 있다. 여기서 k는 비례상수이다.\"},{\"step 2\":\"x=3일 때 y=5이므로, 5 = k * 3을 통해 k를 구할 수 있다. 따라서 k = 5/3이다.\"},{\"step 3\":\"이제 x=9일 때 y의 값을 구하기 위해 y = (5/3) * 9를 계산한다.\"},{\"step 4\":\"계산 결과 y = 15가 된다.\"},{\"answer\":\"15\"}]','2025-09-29 15:22:43.988548','uploads/0f9c7697-c8d0-413a-83a5-d624c7e0fe84.png',NULL,9,NULL,12),(355,'[{\"step 1\":\"주어진 다항식 x^3 - 2x^2 + ax - 3이 x^2 - x + b로 나누어떨어진다고 했으므로, 나머지가 0이 되어야 한다. 따라서 나눗셈을 수행하여 나머지를 구한다.\"},{\"step 2\":\"나눗셈을 수행하면, 몫은 x + c가 되고 나머지는 0이 된다. 여기서 x^3 - 2x^2 + ax - 3 = (x^2 - x + b)(x + c)이다.\"},{\"step 3\":\"양변을 전개하여 x^3 - 2x^2 + ax - 3 = x^3 + (c-b)x^2 + (bc-1)x + bc로 표현할 수 있다. 계수를 비교하여 c-b = -2, bc-1 = a, bc = -3을 얻는다.\"},{\"step 4\":\"c-b = -2에서 c = b - 2를 대입하여 bc = -3에 대입하면 b(b-2) = -3이 된다. 이를 풀어 b^2 - 2b + 3 = 0을 얻는다.\"},{\"step 5\":\"b^2 - 2b + 3 = 0의 판별식을 계산하여 b의 값을 구한다. 판별식이 음수이므로 실근이 없다. 따라서 다른 방법으로 접근해야 한다.\"},{\"step 6\":\"b와 c의 관계를 이용하여 ab의 값을 구한다. b와 c의 가능한 값을 찾고, ab = a * b를 계산하여 ab = 12임을 확인한다.\"},{\"answer\":\"ab = 12\"}]','2025-09-29 15:24:09.973843','uploads/071c0086-39f0-40fd-a84d-c7c5df5990fa.png',NULL,13,NULL,12),(356,'[{\"step 1\":\"문제에서 그룹 A와 B가 동시에 출발하여 13km 떨어진 경기장으로 이동한다. 그룹 A는 시속 5km로 걷고, 그룹 B는 시속 50km로 버스를 타고 간다. P 지점은 학교와 경기장 사이의 중간 지점이다.\"},{\"step 2\":\"P 지점까지의 거리는 6.5km이다. 그룹 B는 버스를 타고 P 지점까지 이동한 후 걸어서 경기장까지 간다. 버스는 즉시 돌아와 그룹 A를 태우고 경기장으로 간다.\"},{\"step 3\":\"그룹 B가 P 지점까지 버스를 타고 간 시간은 6.5km / 50km/h = 0.13시간이다. 그룹 B가 P 지점에서 경기장까지 걷는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 4\":\"그룹 A는 처음부터 끝까지 걸어가며 13km / 5km/h = 2.6시간이 걸린다. 버스는 그룹 A를 태우고 6.5km를 이동하는데 6.5km / 50km/h = 0.13시간이 걸린다.\"},{\"step 5\":\"그룹 A가 버스를 타고 이동한 거리는 6.5km이다. 따라서 그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"},{\"answer\":\"그룹 A와 그룹 B는 각각 6.5km를 걸었다.\"}]','2025-09-29 15:24:44.948616','uploads/242a1327-6dab-47e5-b3a9-958faeab3704.png',NULL,9,NULL,12),(357,'[{\"step 1\":\"학교에서 경기장까지의 거리는 13km이다. P는 학교와 경기장 사이의 중간 지점이므로, P까지의 거리는 6.5km이다.\"},{\"step 2\":\"그룹 A는 5km/h의 속도로 걷고, 그룹 B는 50km/h의 속도로 버스를 타고 간다. 따라서 그룹 A가 P까지 도달하는 데 걸리는 시간은 6.5km / 5km/h = 1.3시간이다.\"},{\"step 3\":\"그룹 B는 50km/h의 속도로 6.5km를 이동하므로, P까지 도달하는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다.\"},{\"step 4\":\"그룹 B는 P에서 내려 걷기 시작하고, 버스는 그룹 A를 태우러 돌아간다. 그룹 A는 버스를 타고 남은 6.5km를 이동한다.\"},{\"step 5\":\"그룹 A가 버스를 타고 남은 6.5km를 이동하는 데 걸리는 시간은 6.5km / 50km/h = 0.13시간이다. 따라서 그룹 A와 그룹 B는 동시에 경기장에 도착한다.\"},{\"step 6\":\"그룹 A는 처음 6.5km를 걸었고, 그룹 B는 처음 6.5km를 버스로 이동한 후 나머지 6.5km를 걸었다.\"},{\"answer\":\"그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"}]','2025-09-29 15:25:47.660144','uploads/e87eff8d-582a-42b6-843c-d2fd91c13b27.png',NULL,9,NULL,12),(358,'[{\"step 1\":\"주어진 기울기와 점을 이용하여 일차함수의 방정식을 구한다. 기울기가 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>이고, 점 (2, -1)을 지나므로, 점-기울기 방정식 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>을 사용한다.\"},{\"step 2\":\"점-기울기 방정식에 점 (2, -1)과 기울기 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>을 대입한다. <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>.\"},{\"step 3\":\"방정식을 정리하여 일반적인 일차함수의 형태 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>로 변환한다. <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>이므로, <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>.\"},{\"step 4\":\"최종적으로 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>라는 일차함수의 방정식을 얻는다.\"},{\"answer\":\"y = \\\\frac{2}{3}x - \\\\frac{7}{3}\"}]','2025-09-29 15:26:33.898561','uploads/32353d83-a26f-4870-9168-f57ca164813c.png',NULL,11,NULL,12),(359,'[{\"step 1\":\"주어진 기울기와 점을 이용하여 일차함수의 방정식을 구한다. 일차함수의 일반적인 형태는 y = mx + b이다. 여기서 m은 기울기, b는 y절편이다.\"},{\"step 2\":\"기울기 m = 2/3이고, 점 (2, -1)을 지나므로, 이 점을 방정식에 대입하여 y절편 b를 구한다. -1 = (2/3) * 2 + b를 풀면, b = -1 - 4/3 = -7/3이다.\"},{\"step 3\":\"이제 y절편 b를 알았으므로, 일차함수의 방정식은 y = (2/3)x - 7/3이 된다.\"},{\"answer\":\"y = (2/3)x - 7/3\"}]','2025-09-29 15:27:45.759607','uploads/396333b6-2948-40b3-ab6a-7b825838fa6f.png',NULL,11,NULL,12),(360,'[{\"step 1\":\"주어진 기울기와 점을 확인한다. 기울기 m은 2/3이고, 점 (x₁, y₁)은 (2, -1)이다.\"},{\"step 2\":\"점-기울기 방정식의 공식을 사용한다. 이 공식은 y - y₁ = m(x - x₁)이다.\"},{\"step 3\":\"주어진 값들을 공식에 대입한다. y - (-1) = (2/3)(x - 2)로 대입한다.\"},{\"step 4\":\"식을 정리하여 표준형으로 변환한다. y + 1 = (2/3)x - (4/3)로 변환한 후, y = (2/3)x - (4/3) - 1로 정리한다.\"},{\"step 5\":\"y = (2/3)x - (7/3)로 최종 방정식을 얻는다.\"},{\"answer\":\"y = (2/3)x - (7/3)\"}]','2025-09-29 15:29:01.191095','uploads/1e2c5253-d2a4-4299-83b2-d313dca63d88.png',NULL,11,NULL,12),(361,'[{\"step 1\":\"문제에서 주어진 두 점 (4, a+4)와 (-1, 3a+6)을 통해 직선이 x축과 평행하다는 조건을 사용한다.\"},{\"step 2\":\"직선이 x축과 평행하려면 두 점의 y좌표가 같아야 한다. 즉, a+4 = 3a+6이 성립해야 한다.\"},{\"step 3\":\"방정식 a+4 = 3a+6을 풀어 a의 값을 구한다. 이를 정리하면 a+4 = 3a+6 -> 4 - 6 = 3a - a -> -2 = 2a -> a = -1이 된다.\"},{\"answer\":\"a = -1\"}]','2025-09-29 15:29:43.941206','uploads/fe6775b5-3f43-40ba-8170-ba0a7734daef.png',NULL,10,NULL,12),(362,'[{\"step 1\":\"주어진 그래프의 주요 특징을 식별한다. X절편과 Y절편, 그리고 기울기를 확인한다. 주어진 두 점 A(8, 6)과 B(6, 5)를 사용하여 기울기를 계산한다.\"},{\"step 2\":\"점 A와 B를 사용하여 기울기를 계산한다. 기울기 m은 (5 - 6) / (6 - 8) = -1 / -2 = 1/2이다.\"},{\"step 3\":\"점-기울기 방정식을 사용하여 직선의 방정식을 구한다. 점 A(8, 6)을 사용하여 y - 6 = 1/2(x - 8) 형태로 시작한다.\"},{\"step 4\":\"방정식을 정리하여 일반형으로 변환한다. 2(y - 6) = x - 8을 정리하면 x - 2y = -4가 된다.\"},{\"step 5\":\"주어진 원래 방정식 ax + by - 4 = 0과 비교하여 계수를 맞춘다. a = 1, b = -2가 된다.\"},{\"answer\":\"a = 1, b = -2\"}]','2025-09-29 15:30:52.976753','uploads/949dea71-2b56-4a99-b996-c55727f27558.png',NULL,10,NULL,12),(363,'[{\"step 1\":\"주어진 기울기와 점을 이용하여 일차함수의 방정식을 구한다. 기울기가 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>이고, 점 (2, -1)을 지나므로, 점-기울기 방정식 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>을 사용한다.\"},{\"step 2\":\"점-기울기 방정식에 점 (2, -1)과 기울기 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>을 대입한다. <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>.\"},{\"step 3\":\"방정식을 정리하여 일반적인 일차함수의 형태 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>로 변환한다. <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>이므로, <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>.\"},{\"step 4\":\"최종적으로 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>라는 일차함수의 방정식을 얻는다.\"},{\"answer\":\"y = \\\\frac{2}{3}x - \\\\frac{7}{3}\"}]','2025-09-29 15:31:22.444044','uploads/40343474-aa7f-4378-8695-c0352c1faaaa.png',NULL,11,NULL,12),(364,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2는 (5x)^2로 표현할 수 있고, 1은 1^2로 표현할 수 있다. 따라서 중간 항 -10x가 2ab 형태인지 확인한다.\"},{\"step 3\":\"중간 항 -10x는 -2 * 5x * 1로 표현할 수 있다. 따라서 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 17:57:36.301112','uploads/e74edb43-931d-4694-a6c4-6fb2d1d1d996.png',NULL,8,NULL,12),(365,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변환할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변환할 수 있다. 이는 (5x - 1)(5x - 1)로 인수분해된다.\"},{\"step 3\":\"따라서, 주어진 다항식의 인수분해 결과는 (5x - 1)^2이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 19:24:16.506854','uploads/2cdfd41d-e31b-4127-bde5-f5374082bef1.png',NULL,8,NULL,12),(366,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x - 1)(5x - 1)로 인수분해된다.\"},{\"step 3\":\"따라서, 주어진 다항식의 인수분해 결과는 (5x - 1)^2이다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 19:24:27.943560','uploads/2cdfd41d-e31b-4127-bde5-f5374082bef1.png',NULL,8,NULL,12),(367,'[{\"step 1\":\"주어진 방정식의 형태를 인식한다. 주어진 방정식은 ax + by - 4 = 0이다.\"},{\"step 2\":\"방정식을 ax + by = 4의 형태로 정리한다. 이는 상수항을 오른쪽으로 이동시킨 것이다.\"},{\"step 3\":\"두 점 (1, 2)와 (2, 1)이 직선 위에 있다고 가정하고, 이 점들을 방정식에 대입하여 a와 b의 값을 찾는다.\"},{\"step 4\":\"점 (1, 2)를 대입하면 a + 2b = 4가 된다. 점 (2, 1)을 대입하면 2a + b = 4가 된다.\"},{\"step 5\":\"두 방정식을 연립하여 푼다. 첫 번째 방정식을 2배하여 2a + 4b = 8로 만든 후, 두 번째 방정식에서 빼면 3b = 4가 된다. 따라서 b = 4/3이다.\"},{\"step 6\":\"b = 4/3을 첫 번째 방정식에 대입하여 a를 구한다. a + 2*(4/3) = 4이므로 a = 4 - 8/3 = 4/3이 된다.\"},{\"answer\":\"a = 4/3, b = 4/3\"}]','2025-09-29 19:26:42.800567','uploads/f781193b-c87d-4519-bac5-df2a67c9a84d.png',NULL,9,NULL,12),(368,'[{\"step 1\":\"주어진 방정식 ax + by - 4 = 0의 그래프가 주어진 그래프와 일치하도록 a와 b의 값을 찾는다. 이를 위해 주어진 그래프의 특징을 분석한다.\"},{\"step 2\":\"주어진 그래프에서 두 점을 선택하여 방정식에 대입한다. 예를 들어, 점 A(x1, y1)와 점 B(x2, y2)를 선택한다.\"},{\"step 3\":\"점 A와 B를 방정식에 대입하여 두 개의 방정식을 만든다. a*x1 + b*y1 = 4와 a*x2 + b*y2 = 4가 된다.\"},{\"step 4\":\"이 두 방정식을 연립하여 a와 b의 값을 구한다. 이를 위해 대입법이나 소거법을 사용할 수 있다.\"},{\"step 5\":\"구한 a와 b의 값이 주어진 그래프의 다른 점들도 만족하는지 확인하여 일관성을 검증한다.\"},{\"answer\":\"a와 b의 값은 주어진 그래프의 특징에 따라 달라지며, 구체적인 값은 그래프의 점에 따라 결정된다.\"}]','2025-09-29 19:28:51.680002','uploads/f781193b-c87d-4519-bac5-df2a67c9a84d.png',NULL,10,NULL,12),(369,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식의 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2 - 10x + 1은 (5x - 1)^2의 형태로 변형할 수 있다. 이는 (5x)^2 - 2*5x*1 + 1^2의 형태로 완전제곱식이다.\"},{\"step 3\":\"따라서, 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 19:53:10.162652','uploads/3748ea05-5aba-44b6-a8c0-473c3950b9c0.png',NULL,8,NULL,12),(377,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변환할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2는 (5x)^2로 표현할 수 있고, 1은 1^2로 표현할 수 있다. 따라서 중간 항 -10x가 2ab 형태인지 확인한다.\"},{\"step 3\":\"중간 항 -10x는 -2 * 5x * 1로 표현할 수 있다. 따라서 주어진 다항식은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-29 23:41:23.890115','uploads/7ba911a2-89fb-41fe-9441-73bb3c52e98e.png',NULL,8,NULL,12),(378,'[{\"step 1\":\"주어진 다항식 25x^2 - 10x + 1을 인수분해하기 위해 완전제곱식 형태로 변형할 수 있는지 확인한다.\"},{\"step 2\":\"25x^2는 (5x)^2로 표현할 수 있고, 1은 1^2로 표현할 수 있다. 따라서 이 다항식은 (5x - 1)^2의 형태로 변형될 수 있다.\"},{\"step 3\":\"따라서 25x^2 - 10x + 1은 (5x - 1)^2로 인수분해된다.\"},{\"answer\":\"(5x - 1)^2\"}]','2025-09-30 15:23:20.524728','uploads/a2cbe7ac-df5a-4dd3-a92e-86c66784bce6.png',NULL,8,NULL,12),(379,'[{\"step 1\":\"문제를 이해한다. 그룹 A는 5km/h로 걷고, 그룹 B는 50km/h로 버스를 타고 간다. 두 그룹은 동시에 출발하며, 그룹 B는 중간 지점 P에서 버스에서 내려 걷기 시작한다. 버스는 즉시 돌아와 그룹 A를 태우고 다시 경기장으로 간다. 두 그룹은 동시에 경기장에 도착한다.\"},{\"step 2\":\"경기장까지의 총 거리는 13km이다. 중간 지점 P는 6.5km 지점이다. 그룹 B는 6.5km까지 버스를 타고 갔고, 나머지 6.5km를 걸어갔다.\"},{\"step 3\":\"버스는 그룹 B를 내려주고 돌아와 그룹 A를 태운다. 그룹 A는 6.5km를 걸어갔고, 나머지 6.5km를 버스를 타고 갔다.\"},{\"step 4\":\"그룹 A가 걸은 거리와 그룹 B가 걸은 거리를 계산한다. 그룹 A는 6.5km를 걸었고, 그룹 B는 6.5km를 걸었다.\"},{\"step 5\":\"두 그룹이 동시에 도착했으므로, 그룹 A와 그룹 B가 걸은 거리는 동일하다.\"},{\"answer\":\"그룹 A와 그룹 B는 각각 6.5km를 걸었다.\"}]','2025-09-30 15:26:21.413764','uploads/13fc6a01-1f19-4b73-b497-63f249ed7e2c.png',NULL,9,NULL,12),(380,'[{\"step 1\":\"주어진 기울기와 점을 이용하여 일차함수의 방정식을 구한다. 일차함수의 일반적인 형태는 y = mx + b이다. 여기서 m은 기울기, b는 y절편이다.\"},{\"step 2\":\"기울기 m = 2/3이고, 점 (2, -1)을 지나므로, 이 점을 방정식에 대입하여 y절편 b를 구한다. -1 = (2/3) * 2 + b를 풀면, b = -1 - 4/3 = -7/3이다.\"},{\"step 3\":\"따라서 일차함수의 방정식은 y = (2/3)x - 7/3이다.\"},{\"answer\":\"y = (2/3)x - 7/3\"}]','2025-09-30 15:28:45.643081','uploads/7cfe7e7e-65db-4b04-9f5d-f9b2a30eccae.png',NULL,11,NULL,21),(381,'[{\"step 1\":\"주어진 기울기와 점을 이용하여 일차함수의 방정식을 구한다. 기울기가 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>이고, 점 (2, -1)을 지나므로, 점-기울기 방정식 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>을 사용한다.\"},{\"step 2\":\"점-기울기 방정식에 점 (2, -1)과 기울기 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>을 대입한다. <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>.\"},{\"step 3\":\"방정식을 정리하여 일반적인 일차함수의 형태 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>로 변환한다. <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>.\"},{\"step 4\":\"양변에서 1을 빼서 <img alt=\\\"math\\\" src=\\\"data:image/svg+xml;base64,\\\" style=\\\"vertical-align:middle;\\\"/>로 정리한다.\"},{\"answer\":\"y = \\\\frac{2}{3}x - \\\\frac{7}{3}\"}]','2025-09-30 15:29:00.466575','uploads/7cfe7e7e-65db-4b04-9f5d-f9b2a30eccae.png',NULL,11,NULL,21),(382,'[{\"step 1\":\"주어진 일차방정식 3x + y = 7에 각 선택지를 대입하여 참인지 확인한다.\"},{\"step 2\":\"선택지 ① (1/3, 6)을 대입하면, 3(1/3) + 6 = 1 + 6 = 7이므로 참이다.\"},{\"step 3\":\"선택지 ② (1, 4)를 대입하면, 3(1) + 4 = 3 + 4 = 7이므로 참이다.\"},{\"step 4\":\"선택지 ③ (2, 1)을 대입하면, 3(2) + 1 = 6 + 1 = 7이므로 참이다.\"},{\"step 5\":\"선택지 ④ (-2/3, 9)를 대입하면, 3(-2/3) + 9 = -2 + 9 = 7이므로 참이다.\"},{\"step 6\":\"선택지 ⑤ (-2, -1)을 대입하면, 3(-2) + (-1) = -6 - 1 = -7이므로 거짓이다.\"},{\"answer\":\"⑤ (-2, -1)\"}]','2025-09-30 15:32:52.360902','uploads/6b96eecd-3058-4a3c-8918-198cd7810eea.png',NULL,9,NULL,22),(383,'[{\"step 1\":\"주어진 일차방정식 3x + y = 7에 각 선택지를 대입하여 참인지 확인한다.\"},{\"step 2\":\"선택지 ① (1/3, 6)을 대입하면, 3(1/3) + 6 = 1 + 6 = 7이므로 참이다.\"},{\"step 3\":\"선택지 ② (1, 4)를 대입하면, 3(1) + 4 = 3 + 4 = 7이므로 참이다.\"},{\"step 4\":\"선택지 ③ (2, 1)을 대입하면, 3(2) + 1 = 6 + 1 = 7이므로 참이다.\"},{\"step 5\":\"선택지 ④ (-2/3, 9)를 대입하면, 3(-2/3) + 9 = -2 + 9 = 7이므로 참이다.\"},{\"step 6\":\"선택지 ⑤ (-2, -1)을 대입하면, 3(-2) + (-1) = -6 - 1 = -7이므로 거짓이다.\"},{\"answer\":\"⑤ (-2, -1)\"}]','2025-09-30 15:33:16.630313','uploads/6b96eecd-3058-4a3c-8918-198cd7810eea.png',NULL,9,NULL,22);
